(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('spectacularly','Spectacularly is formed from spectacular and -ly; it means in a dramatic, impressive, or eye-catching way.',C('spectacularly.s1','壮观地；令人惊叹地','The northern lights appeared spectacularly above the lake, shifting from green to violet as the sky darkened.','天色渐暗时，北极光壮观地出现在湖面上空，从绿色变为紫色。','The northern lights appeared spectacularly / above the lake / as the sky darkened.','spectacularly.s1 指以戏剧性、令人印象深刻的方式发生或呈现。','颜色变化和开阔夜空构成醒目的景象。'),M('The northern lights appeared spectacularly as a faint, ordinary glow that nobody noticed.','The lights appeared dramatically and impressed the observers.','无人注意的微弱普通光线不符合 spectacularly 的醒目意味。','meaning'),[q('Where did the northern lights appear?','above the lake','under the lake’s surface','inside a theater','北极光出现在湖面上空。',1,'context'),q('How did their colors change?','from green to violet','from red to black only','they did not change at all','北极光从绿色变为紫色。',1,'context'),q('What does spectacularly describe?','a dramatic and impressive appearance','a quiet, unnoticed event','a careful spelling correction','spectacularly 表示以壮观、令人印象深刻的方式呈现。',1,'meaning'),q('Which scene happens spectacularly?','a waterfall suddenly lit by vivid sunlight','a plain wall viewed in a dark closet','a letter typed with no display','被鲜明阳光照亮的瀑布壮观地出现。',1,'context')]);
P('spectator','Spectator comes from Latin spectare, “to watch”; it means a person who watches a match, show, or event, or someone who sees an event without taking part.',[C('spectator.s1','观众；观看者','Each spectator in the stadium stood as the runners approached the finish line.','跑者接近终点时，体育场里的每位观众都站了起来。','Each spectator stood / as the runners approached / the finish line.','spectator.s1 指观看体育比赛、演出或公共活动的人。','观众观看跑步比赛。'),C('spectator.s2','旁观者','A spectator to the street argument called for help but did not join the dispute.','街头争执的一名旁观者叫人求助，但没有加入争吵。','A spectator called for help / but did not join / the street dispute.','spectator.s2 指看到事情发生但没有参与其中的人。','旁观者没有参加争执。')],M('A spectator in the race was one of the runners competing for the finish line.','A spectator watched the race without competing in it.','参赛者参与比赛，不是观看比赛的 spectator。','meaning'),[q('What did spectators watch in the stadium?','the runners approaching the finish line','a cooking class in a kitchen','a street argument they started','观众观看跑者接近终点。',1,'context'),q('What did the street spectator do?','called for help without joining the dispute','joined the argument and struck someone','ran in the stadium race','旁观者求助但没有加入争执。',2,'context'),q('Who is a spectator at a match?','a person who watches it','a player competing in it','the person who writes the team speech','比赛中的 spectator 是观看者。',1,'meaning'),q('What distinguishes the second spectator sense?','seeing an event without taking part','competing for a medal','performing on a stage','旁观者看到了事件但没有参与。',1,'meaning')]);
P('spectators','Spectators is the plural of spectator, from Latin spectare, “to watch”; it means people who watch a match, show, or event, or by extension a person who observes without joining.',[C('spectators.s1','观众','The spectators clapped when the orchestra returned to the stage for an encore.','乐团返场加演时，观众鼓起掌来。','The spectators clapped / when the orchestra returned / for an encore.','spectators.s1 是 spectator 的复数，指观看比赛、演出或活动的人。','观众观看乐团演出并鼓掌。'),C('spectators.s2','旁观者','The spectators watched the rescue from behind the barrier and left the trained crew to work.','旁观者隔着护栏观看救援，让受过训练的救援队处理现场。','The spectators watched from behind the barrier / and left the crew / to work.','spectators.s2 指观察事件但没有亲自参与的人。','旁观者没有加入救援工作。')],M('The spectators at the concert were the musicians playing onstage rather than people watching them.','The spectators watched the orchestra perform from the seats.','舞台上的演奏者是表演者，不是观众。','meaning'),[q('What did the spectators do when the orchestra returned?','clapped','left before hearing any music','joined the musicians onstage','乐团返场时，观众鼓掌。',1,'context'),q('Where did the rescue spectators watch from?','behind the barrier','inside the rescue vehicle','on the finish line','旁观者隔着护栏观看救援。',2,'context'),q('What does spectators mean at a concert?','people watching the performance','the musicians performing','the stage curtains','spectators 指观看音乐会的观众。',1,'meaning'),q('What does the second sense emphasize?','observers who do not join the event','people who lead the rescue','workers carrying the barrier','第二义强调观察但不参与事件的人。',2,'meaning')]);
P('spectral','Spectral is formed from spectre/spectrum and -al; it means relating to a spectrum of light, sound, or radiation.',C('spectral.s1','光谱的','The astronomer compared spectral lines from the star to identify the elements in its atmosphere.','天文学家比较恒星的光谱线，以辨认其大气中的元素。','The astronomer compared spectral lines / from the star / to identify elements.','spectral.s1 指与光、声或辐射的光谱有关。','光谱线帮助分析恒星成分。'),M('The astronomer called the lines spectral although they contained no measurable pattern from light or radiation.','The lines formed a measurable spectrum that revealed the star’s elements.','没有光谱图样或测量依据的线不能支持 spectral 分析。','meaning'),[q('What did the astronomer compare?','spectral lines from the star','the star’s spoken name','a map of the stadium','天文学家比较恒星的光谱线。',1,'context'),q('What did the lines help identify?','elements in the star’s atmosphere','the number of spectators','the age of a theater','光谱线帮助辨认恒星大气中的元素。',1,'context'),q('What does spectral mean?','relating to a spectrum of light, sound, or radiation','relating to a live audience','happening at a very high speed','spectral 指与光、声或辐射的光谱有关。',1,'meaning'),q('Which measurement is spectral?','the wavelengths of colored light from a star','the number of seats in a concert hall','the length of a runner’s stride','恒星彩色光线的波长测量属于 spectral。',1,'context')]);
P('spectroscopic','Spectroscopic is formed from spectroscopy and -ic; it means using or concerning the measurement and study of spectra.',C('spectroscopic.s1','光谱学的；分光的','Researchers used spectroscopic analysis to determine which gases surrounded the distant planet.','研究人员利用光谱分析确定遥远行星周围有哪些气体。','Researchers used spectroscopic analysis / to determine / the planet’s gases.','spectroscopic.s1 指使用或涉及对光谱的测量与研究。','分析光谱以判断气体成分。'),M('The researchers called their work spectroscopic although they measured only the planet’s weight and never examined a spectrum.','They analyzed spectra to identify gases around the planet.','没有测量或研究光谱，就不属于 spectroscopic analysis。','meaning'),[q('What did the researchers examine?','spectra from the distant planet','the planet’s written name','the spectators’ tickets','研究人员利用光谱分析行星周围气体。',1,'context'),q('What were they trying to determine?','which gases surrounded the planet','how many people watched the launch','whether the planet had a stadium','研究人员要确定行星周围有哪些气体。',1,'context'),q('What does spectroscopic mean?','using or concerning the measurement of spectra','relating to watching a public event','relating to spelling words aloud','spectroscopic 指使用光谱测量或研究的。',1,'meaning'),q('Which method is spectroscopic?','identifying a gas from its light spectrum','counting seats from a printed map','timing runners with a stopwatch','根据光谱辨认气体属于 spectroscopic 方法。',1,'context')]);
P('spectrum','Spectrum comes from Latin spectrum, “appearance”; it can mean the colors made by separating light or a complete range of opinions, types, or qualities.',[C('spectrum.s1','光谱','A prism spread white sunlight into a spectrum of colors on the laboratory wall.','棱镜把白色阳光分散成一道彩色光谱，映在实验室墙上。','A prism spread sunlight / into a spectrum of colors / on the wall.','spectrum.s1 指光分解后形成的一系列颜色。','棱镜把白光分解为多种颜色。'),C('spectrum.s2','范围；系列','The survey included voters across the political spectrum, from green activists to fiscal conservatives.','这项调查涵盖了政治立场光谱各端的选民，从环保活动人士到财政保守派。','The survey included voters across the political spectrum / from green activists / to fiscal conservatives.','spectrum.s2 指意见、类型或特征构成的完整范围。','受访者涵盖不同政治立场。')],M('The prism created a spectrum of colors by leaving the white light unchanged and unseparated.','The prism separated white light into a range of colors.','白光未被分解就不会产生这里所说的彩色光谱。','meaning'),[q('What did the prism spread?','white sunlight','a group of voters','a speech draft','棱镜把白色阳光分散成彩色光谱。',1,'context'),q('Which voters did the survey include?','people from different political positions','only one political party’s leaders','only the laboratory staff','调查涵盖了不同政治立场的选民。',2,'context'),q('What is a spectrum in the prism example?','the colors produced when light is separated','the people watching an event','a short period of weather','棱镜例句中的 spectrum 指分光后形成的颜色序列。',1,'meaning'),q('What does across the political spectrum mean?','through a broad range of political opinions','only at one end of a rainbow','across a sports field','across the political spectrum 指涵盖广泛的政治观点。',2,'meaning')]);
P('speculate','Speculate comes from Latin speculari, “to observe”; it can mean guess without all the facts or buy/sell hoping to profit from price changes.',[C('speculate.s1','推测；猜测','Without a confirmed report, reporters refused to speculate about why the ferry had turned back.','没有确切报道，记者拒绝猜测渡船为何返航。','Reporters refused to speculate / without a confirmed report / about the ferry’s return.','speculate.s1 指在事实不全时推测某事。','缺乏证据时记者不妄加猜测。'),C('speculate.s2','投机；做投机买卖','Some traders speculate in wheat futures, accepting the risk that prices may move against them.','一些交易者投机买卖小麦期货，并承担价格可能朝不利方向变化的风险。','Some traders speculate in wheat futures / accepting the risk / of an adverse price move.','speculate.s2 指为快速获利而买卖商品或证券，伴有亏损风险。','交易者承担价格波动的风险。')],M('The reporters speculated about the ferry after receiving a confirmed official explanation and complete evidence.','They guessed about the cause because no confirmed report was available.','有官方证实的完整信息时，报道不再是无根据的猜测。','meaning'),[q('Why did reporters avoid speculating?','there was no confirmed report','the ferry had never existed','they were trading wheat futures','记者没有确切报道，所以避免猜测。',1,'context'),q('What did the traders speculate in?','wheat futures','the ferry’s passenger list','a prism’s colors','交易者投机买卖小麦期货。',2,'context'),q('What does speculate mean in the news example?','guess without knowing all the facts','buy crops for immediate use','measure a spectrum','新闻例句中的 speculate 指在事实不全时猜测。',1,'meaning'),q('What risk do speculators accept?','prices may move against them and cause a loss','a confirmed report may be printed','a prism may separate colors','投机者承担价格不利变动造成亏损的风险。',2,'context')]);
P('speculation','Speculation comes from Latin speculatio; it can mean unfounded guesses about events or buying goods, shares, or property in hope of a price profit.',[C('speculation.s1','推测；猜测','The rumor about a merger remained speculation until both companies released a signed statement.','关于合并的传闻在两家公司发布签署声明前仍只是猜测。','The merger rumor remained speculation / until both companies / released a signed statement.','speculation.s1 指缺乏确凿证据、对可能发生之事的猜测。','正式声明尚未发布时，传闻没有证实。'),C('speculation.s2','投机；炒作','Speculation in vacant lots drove prices up, although buyers had no immediate plans to build there.','对空地的投机买卖推高了价格，尽管买家近期并无建房计划。','Speculation in vacant lots drove prices up / though buyers had / no building plans.','speculation.s2 指为从价格变化获利而买卖资产。','买家看重的是地价上涨，而非实际使用。')],M('The merger announcement was speculation even though both firms had issued the same signed statement confirming it.','Before an official statement, the merger rumor was only an unconfirmed guess.','两家公司共同签署的正式声明不是无根据猜测。','meaning'),[q('When did the rumor stop being speculation?','after both companies released a signed statement','before either company existed','when buyers built on every vacant lot','两家公司发布签署声明后，合并传闻才获得确认。',1,'context'),q('What did land speculation cause?','prices for vacant lots rose','all buyers stopped trading','the lots became a spectrum','空地投机买卖推高了价格。',2,'context'),q('What does speculation mean about the rumor?','an unfounded guess without firm evidence','a confirmed legal statement','a measured light spectrum','这里 speculation 指没有确凿证据的猜测。',1,'meaning'),q('What does speculation mean in the vacant-lot example?','buying property to profit from price changes','building a home for immediate use','measuring land with a ruler','空地例句中的 speculation 指为赚取价格差而投机买卖。',1,'meaning')]);
P('speculative','Speculative is formed from speculate and -ive; it means based on guesses rather than evidence, or involving risky trades made for profit.',[C('speculative.s1','推测的；猜想的','The article labeled its account speculative because no witness could confirm the proposed cause of the blackout.','文章把这套说法称为推测性的，因为没有目击者能证实停电原因。','The article called its account speculative / because no witness / confirmed the cause.','speculative.s1 指依据猜测而非可靠证据的。','没有目击者证实该解释。'),C('speculative.s2','投机的','The fund avoided speculative property deals that promised high returns but could lose the entire investment.','基金避开了那些承诺高回报、却可能赔掉全部投资的房地产投机交易。','The fund avoided speculative property deals / that promised high returns / but risked total loss.','speculative.s2 指为了获利而进行、同时可能造成损失的投机活动。','交易回报高但风险也大。')],M('The article called the claim speculative after several independent witnesses confirmed it with records.','It was speculative because no witness or record supported the proposed cause.','多名证人和记录证实的说法并非基于猜测。','meaning'),[q('Why did the article call the blackout explanation speculative?','no witness could confirm it','official records proved it','the blackout was a light spectrum','没有目击者能证实停电原因，所以说法是推测性的。',1,'context'),q('What risk did the property deals carry?','they could lose the entire investment','they had no chance of losing money','they were guaranteed government grants','房地产投机交易可能让投资全部亏损。',2,'context'),q('What does speculative mean in the article example?','based on guesses rather than evidence','confirmed by records','measured with a spectroscope','文章里的 speculative 指缺乏证据、基于猜测的。',1,'meaning'),q('What makes an investment speculative?','it seeks a large gain but carries a risk of loss','it has a guaranteed fixed return','it is used only for long-term housing','投机投资追求高收益，也承担亏损风险。',2,'meaning')]);
P('speculator','Speculator is formed from speculate and -or; it means someone who risks money on price changes rather than buying for long-term use.',C('speculator.s1','投机者','The speculator bought copper futures only because she expected the market price to rise next week.','这名投机者买入铜期货，只因为她预计下周市场价格会上涨。','The speculator bought copper futures / expecting the market price / to rise next week.','speculator.s1 指为价格变化可能带来的利润而承担风险的人。','买入期货的理由是预期短期涨价。'),M('The speculator bought the copper solely to build a factory and had no interest in changes to its price.','She risked money on a possible price increase instead of purchasing copper for long-term use.','为工厂长期使用而采购并非价格投机。','meaning'),[q('Why did the speculator buy copper futures?','she expected the price to rise next week','she needed copper for a factory today','she wanted to watch a concert','她预期下周价格会上涨，因此买入期货。',1,'context'),q('What did she buy?','copper futures','a speech draft','a theater ticket','投机者买入铜期货。',1,'context'),q('What is a speculator?','someone risking money on price changes','someone who writes speeches','someone who watches a match','speculator 指为价格变化获利而承担风险的人。',1,'meaning'),q('Which buyer is a speculator?','one trading shares for a hoped-for quick price gain','one buying metal to use in a machine','one studying spectral lines','为短期涨价获利而交易股票的人是 speculator。',1,'context')]);
P('speech','Speech comes from Old English spæc; it can mean the ability or act of speaking, a formal talk, or a particular manner of speaking.',[C('speech.s1','说话能力；言语','After the operation, the patient gradually regained speech and could form short sentences again.','手术后，病人逐渐恢复了说话能力，又能说出简短句子。','The patient gradually regained speech / and could form / short sentences again.','speech.s1 指说话能力或口头语言。','病人恢复了表达能力。'),C('speech.s2','演讲；发言','The mayor delivered a speech about flood prevention to residents gathered in the school hall.','市长在学校礼堂向居民发表了防洪演讲。','The mayor delivered a speech / about flood prevention / to gathered residents.','speech.s2 指面向听众所作的正式讲话。','市长对居民发表正式讲话。'),C('speech.s3','口音；说话方式','Her speech still carried a regional accent after she had lived abroad for many years.','她在国外生活多年后，说话仍带有地方口音。','Her speech still carried a regional accent / after many years / abroad.','speech.s3 可指一个人特有的说话方式或口音。','她的言语保留地方特征。')],M('The patient regained speech but remained unable to utter any word or communicate verbally.','The patient regained the ability to speak and formed short sentences.','完全不能说话与恢复 speech 相矛盾。','meaning'),[q('What did the patient regain?','the ability to speak','the mayor’s office','a regional train ticket','病人逐渐恢复了说话能力。',1,'context'),q('What was the mayor’s speech about?','flood prevention','spectral lines','how to spell the word “speech”','市长的演讲主题是防洪。',2,'context'),q('What did her speech still carry?','a regional accent','a formal flood plan','a period of silence','她说话仍带地方口音。',3,'context'),q('What is a speech in the mayor example?','a formal talk to an audience','the physical ability to articulate','a regional accent only','市长例句中的 speech 指面向听众的正式讲话。',2,'meaning')]);
P('speechless','Speechless combines speech and -less; it means unable to find words from shock or upset, or simply silent.',[C('speechless.s1','（震惊等而）说不出话的','Mara was speechless when the team surprised her with a recording from her brother overseas.','队友拿出她海外哥哥寄来的录音给她惊喜时，玛拉震惊得说不出话来。','Mara was speechless / when the team surprised her / with her brother’s recording.','speechless.s1 指因震惊、愤怒等一时找不到话说。','突如其来的惊喜令她无言。'),C('speechless.s2','沉默的；一言不发的','After the chair invited questions, the room stayed speechless for a moment because no one had anything to add.','主持人邀请提问后，大家一时都没有发言，因为无人有补充意见。','The room stayed speechless for a moment / after questions were invited / because no one had more to add.','speechless.s2 指保持沉默，可能出于选择或无话可说。','房间里的人没有补充问题。')],M('Mara was speechless with surprise, so she delivered a long prepared reply immediately.','The unexpected recording left Mara unable to find words at first.','立刻发表长篇回应与当时说不出话不符。','meaning'),[q('Why was Mara speechless?','her teammates surprised her with a recording','she had already written a speech','the room had no chairs','哥哥的录音让玛拉震惊得说不出话。',1,'context'),q('Why did the room stay speechless after questions?','no one had anything to add','everyone was shouting answers','the chair canceled the meeting','大家没有补充意见，所以暂时沉默。',2,'context'),q('What does speechless mean in Mara’s case?','unable to find words from surprise','choosing to whisper politely','having a strong regional accent','玛拉因惊喜而一时说不出话。',1,'meaning'),q('What does speechless mean about the room?','silent because nobody spoke','filled with formal speeches','unable to hear any sound','房间例句里的 speechless 指无人发言、保持沉默。',2,'meaning')]);
P('speechwriter','Speechwriter combines speech and writer; it means a person employed to draft speeches delivered by a public figure.',C('speechwriter.s1','演讲撰稿人','The president’s speechwriter revised the address after the science advisers corrected two figures.','科学顾问更正了两个数据后，总统的演讲撰稿人修改了讲稿。','The speechwriter revised the address / after advisers corrected / two figures.','speechwriter.s1 指为公众人物起草演讲稿的人。','撰稿人根据顾问更正修改讲话内容。'),M('The speechwriter delivered the president’s address as the elected official while someone else wrote it.','The speechwriter drafted and revised the address for the president to deliver.','代表公众人物发表讲话的人是演讲者，不是撰稿人。','meaning'),[q('What did the advisers correct?','two figures','the speechwriter’s accent','the audience’s seats','科学顾问更正了两个数据。',1,'context'),q('What did the speechwriter revise?','the president’s address','the science advisers’ laboratory','a stadium race result','撰稿人修改了总统的演讲稿。',1,'context'),q('What is a speechwriter?','someone employed to draft speeches for a public figure','the official who always delivers every speech','a spectator at a public event','speechwriter 指替公众人物起草演讲稿的人。',1,'meaning'),q('Who would be a speechwriter?','a worker preparing a minister’s remarks','a person listening to a minister speak','a technician measuring star spectra','为部长准备发言稿的人是 speechwriter。',1,'context')]);
P('speed','Speed comes from Old English spēd; it can mean a rate of movement, the quality of being fast, or move/drive quickly.',[C('speed.s1','速度；速率','The sensor measured the speed of the river current after heavy rain.','暴雨后，传感器测量了河流的流速。','The sensor measured the speed / of the river current / after heavy rain.','speed.s1 指运动或变化的快慢程度。','传感器记录水流快慢。'),C('speed.s2','快速；迅速','The rescue team worked with speed to reach the stranded hikers before nightfall.','救援队迅速行动，赶在天黑前抵达被困的徒步者身边。','The rescue team worked with speed / to reach the hikers / before nightfall.','speed.s2 作名词，指行动迅速这一特质。','救援队快速行动。'),C('speed.s3','快速行进；超速','The driver was fined for speeding through the school zone at noon.','司机因中午在学校区域超速而被罚款。','The driver was fined / for speeding through the school zone / at noon.','speed.s3 作动词可指快速行进，也可特指超速驾驶。','司机超过限速行驶。')],M('The sensor measured the river’s speed while the current remained perfectly motionless.','The sensor measured how fast the river current was flowing.','静止的水流没有可测的流速。','meaning'),[q('What did the sensor measure?','the river current’s speed','the hikers’ speech','the water’s color spectrum','传感器测量了河流的流速。',1,'context'),q('When did the rescue team reach the hikers?','before nightfall','after the next winter','before the rain began years earlier','救援队赶在天黑前到达。',2,'context'),q('Why was the driver fined?','for speeding in a school zone','for speaking at a school','for measuring river water','司机因在学校区域超速被罚款。',3,'context'),q('What does speed mean in the sensor sentence?','the rate at which the current moves','the fast quality of the rescue team','the act of writing a speech','这里 speed 指水流移动的速率。',1,'meaning')]);
P('speed up','Speed up combines speed and up; it can mean begin moving/happening faster or make a process finish sooner.',[C('speed up.s1','（自己）加速','The train began to speed up as it left the station and entered the open track.','列车驶离车站、进入开阔轨道后开始加速。','The train began to speed up / as it left the station / and entered open track.','speed up.s1 不及物用法，指自身开始变快。','列车离站后速度增加。'),C('speed up.s2','使加快；加速','Adding a second editor should speed up the review of the long report.','增加一名编辑应该能加快这份长报告的审阅进度。','A second editor should speed up the review / of the long report / this week.','speed up.s2 及物用法，指使活动或过程更快完成。','增加编辑能缩短审阅时间。')],M('The train began to speed up by slowing down before entering the open track.','The train accelerated as it left the station.','减速与 speed up 所指的加速相反。','meaning'),[q('When did the train speed up?','after leaving the station','while standing at the platform','before arriving at the station and braking','列车驶离车站后开始加速。',1,'context'),q('What should a second editor do?','make the report review faster','make the report longer','cancel the report’s publication','增加一名编辑应该加快审阅进度。',2,'context'),q('What does speed up mean in the train example?','begin to move faster','make another person work faster','write more quickly by hand','列车例句中的 speed up 指自身加速。',1,'meaning'),q('What does speed up mean when taking the review as its object?','make the process finish sooner','start moving without an object','measure the report’s length','speed up the review 指加快审阅过程。',2,'meaning')]);
P('speedup','Speedup combines speed and up; it means an increase in speed or a period when growth/activity accelerates.',[C('speedup.s1','加速；提速','The new processor delivered a speedup that cut image-rendering time from four minutes to one.','新处理器带来了提速，把图像渲染时间从四分钟缩短到一分钟。','The new processor delivered a speedup / cutting rendering time / from four minutes to one.','speedup.s1 指速度增加或处理时间缩短。','渲染时间大幅减少体现性能提速。'),C('speedup.s2','加速期；活跃期','The plant’s spring speedup began when warmer days led to a rapid increase in new shoots.','天气转暖、嫩芽迅速增多时，植物进入春季加速生长期。','The plant’s spring speedup began / when warmer days / brought rapid new shoots.','speedup.s2 指增长或活动比前一阶段更快的一段时期。','春季新芽增长加快。')],M('The processor produced a speedup by increasing the rendering time from one minute to four.','It produced a speedup because rendering fell from four minutes to one.','处理时间变长不是 speedup。','meaning'),[q('How did rendering time change?','from four minutes to one','from one minute to four','it stayed at four hours','新处理器把渲染时间从四分钟缩短到一分钟。',1,'context'),q('What marked the plant’s spring speedup?','a rapid increase in new shoots','the leaves stopping growth','a drop in temperature below freezing','嫩芽迅速增多标志着植物进入加速生长期。',2,'context'),q('What does speedup mean about the processor?','an increase in processing speed','a four-minute delay added to each task','a reduction in memory capacity','此处 speedup 指处理速度的提升。',1,'meaning'),q('What is a speedup in the plant example?','a period of faster growth than before','a machine’s reduced processing rate','a sudden end to all activity','植物例句中的 speedup 指增长比之前更快的一段时期。',2,'meaning')]);
P('speedy','Speedy is formed from speed and -y; it means moving or acting quickly.',C('speedy.s1','快速的；迅速的','The clinic arranged a speedy transfer so the injured cyclist could receive specialist care that afternoon.','诊所安排了快速转运，让受伤的骑行者当天下午就能接受专科治疗。','The clinic arranged a speedy transfer / so the cyclist / could receive care that afternoon.','speedy.s1 指行动或进程迅速的。','快速转运确保及时治疗。'),M('The clinic arranged a speedy transfer that kept the cyclist waiting for three weeks.','The clinic moved the injured cyclist quickly for same-day treatment.','等待数周不符合 speedy 的迅速含义。','meaning'),[q('Who needed the transfer?','the injured cyclist','the speechwriter','the stadium spectators','受伤的骑行者需要转运。',1,'context'),q('When could the cyclist receive specialist care?','that afternoon','three weeks later','before the accident occurred','骑行者当天下午就能接受专科治疗。',1,'context'),q('What does speedy mean?','moving or acting quickly','careless and dirty','based only on guesses','speedy 指迅速的。',1,'meaning'),q('Which response is speedy?','an ambulance reaches the clinic in minutes','a referral is processed after several months','a train remains stopped all day','救护车几分钟内抵达诊所是 speedy 的行动。',1,'context')]);
P('spell','Spell has several origins and senses: write letters in order, mean or bring about a result, a short period, or magic words.',[C('spell.s1','拼写','Could you spell your surname slowly so I can enter each letter correctly?','你能慢慢拼出姓氏吗？这样我就能正确输入每个字母。','Could you spell your surname / slowly / so I can enter each letter?','spell.s1 作动词，指按正确顺序说出或写出字母。','说出字母以便正确记录姓名。'),C('spell.s2','意味着；招致','A sudden loss of funding could spell trouble for the community clinic.','资金突然减少可能给社区诊所带来麻烦。','A sudden loss of funding could spell trouble / for the community clinic / this year.','spell.s2 指意味着某种结果，通常是不好的结果。','资金减少预示困难。'),C('spell.s3','一段时间；一阵','A dry spell lasted three weeks, leaving the garden soil cracked and dusty.','一段干旱期持续了三周，花园土壤变得干裂、满是灰尘。','A dry spell lasted three weeks / leaving garden soil / cracked and dusty.','spell.s3 作名词，指某种天气或活动持续的一段时间。','干旱持续了三周。'),C('spell.s4','咒语；魔力','In the folktale, the witch cast a spell that made the prince sleep until sunrise.','民间故事里，女巫施了咒语，让王子一直睡到日出。','The witch cast a spell / that made the prince sleep / until sunrise.','spell.s4 作名词，指被认为具有魔力的词句。','咒语使王子入睡。')],M('Please spell your surname by skipping several letters and changing their order.','Say each letter in the correct sequence so the name can be recorded accurately.','颠倒或漏掉字母不是正确拼写。','meaning'),[q('What did the speaker ask the person to spell?','their surname','the clinic’s address','the dry garden soil','对方需要慢慢拼出自己的姓氏。',1,'context'),q('What could a sudden funding loss spell for the clinic?','trouble','a dry spell in the garden','a magic sleep','资金骤减可能给社区诊所带来麻烦。',2,'context'),q('How long did the dry spell last?','three weeks','until sunrise only','four minutes','干旱期持续了三周。',3,'context'),q('What did the witch cast?','a magic spell','a surname list','a funding report','女巫施了魔法咒语。',4,'context')]);
P('spellbind','Spellbind combines spell and bind; it means fascinate someone so completely that they keep watching or listening.',C('spellbind.s1','迷住；使着迷','The storyteller’s quiet voice and vivid details spellbound the children until the final page.','讲故事者平静的声音和生动细节让孩子们着迷，直到读完最后一页。','The storyteller’s voice and details spellbound the children / until / the final page.','spellbind.s1 指使人全神贯注，舍不得移开目光或停止聆听。','孩子们一直专注地听故事。'),M('The storyteller spellbound the children by making them bored enough to leave before the first page.','The vivid story held the children’s attention through the final page.','孩子们因无聊离场不符合 spellbind 所表达的着迷。','meaning'),[q('What held the children’s attention?','the storyteller’s voice and vivid details','a blank wall','the audience’s ticket prices','讲故事者的声音和细节让孩子们着迷。',1,'context'),q('How long did the children listen?','until the final page','only before the story began','for one second and then left','孩子们一直听到最后一页。',1,'context'),q('What does spellbind mean?','fascinate so someone keeps watching or listening','write a word’s letters correctly','make an event happen faster','spellbind 指使人着迷、持续专注。',1,'meaning'),q('Which performance could spellbind an audience?','a vivid tale that keeps listeners absorbed','a silent blank screen that everyone ignores','a speech with no audience','让听众一直专注的生动故事可以 spellbind 观众。',1,'context')]);
P('spelling','Spelling is formed from spell and -ing; it means the correct sequence of letters in a word or a person’s ability to produce it.',C('spelling.s1','拼写；拼法','The editor checked the spelling of each place name against the official map before printing the guide.','编辑在印制指南前，对照官方地图核对了每个地名的拼写。','The editor checked each place name’s spelling / against the official map / before printing.','spelling.s1 指词语中字母的正确排列，也可指拼写能力。','编辑核验地名拼法。'),M('The editor checked each name’s spelling by rearranging its letters into a different, incorrect sequence.','The editor verified the correct letter sequence against the official map.','把字母排错不是检查正确拼写。','meaning'),[q('What did the editor check?','the spelling of each place name','the speed of the printing press','the audience’s speech','编辑核对了每个地名的拼写。',1,'context'),q('What source did the editor use?','the official map','a weather report','a phone photograph','编辑对照官方地图核查地名。',1,'context'),q('What is spelling?','the correct sequence of letters in a word','a dramatic performance','a period of dry weather','spelling 指词语中字母的正确排列。',1,'meaning'),q('Which task tests spelling ability?','writing the letters of a word in their correct order','measuring how fast a river flows','watching a race from the stands','按正确顺序写出词中字母是在测试拼写能力。',1,'context')]);
P('spend','Spend comes from Old English spendan, borrowed from Latin expendere; it can mean use money, use time, or use up a supply.',[C('spend.s1','花费（金钱）','The museum will spend part of its grant on safer display cases for the fragile pottery.','博物馆将把部分拨款用于为易碎陶器购买更安全的展示柜。','The museum will spend part of its grant / on safer cases / for fragile pottery.','spend.s1 指用钱购买或支付某物。','拨款用于购买展示柜。'),C('spend.s2','度过；花费（时间）','We spent the afternoon cataloguing fossils in the university collection.','我们整个下午都在整理大学馆藏中的化石。','We spent the afternoon / cataloguing fossils / in the collection.','spend.s2 指把一段时间用于某活动或某处。','下午用于整理化石。'),C('spend.s3','耗尽；用完','The hikers had spent all their drinking water before reaching the next campsite.','徒步者抵达下一个营地前已经耗尽了所有饮用水。','The hikers had spent all their water / before reaching / the next campsite.','spend.s3 指使用某物直到所剩无几或用完。','抵达营地前水已用完。')],M('The museum spent its grant on display cases by keeping every dollar unspent in the account.','It used some grant money to buy safer cases.','钱留在账户中未被使用，与 spend 相反。','meaning'),[q('What will the museum spend grant money on?','safer display cases','a new speechwriter','drinking water for hikers','博物馆会把拨款用于购买展示柜。',1,'context'),q('What did the group spend the afternoon doing?','cataloguing fossils','watching a race','buying a theater','他们整个下午都在整理化石。',2,'context'),q('What had the hikers spent before reaching camp?','all their drinking water','all the museum’s grant money','their fossil collection','徒步者抵达营地前用完了饮用水。',3,'context'),q('What does spend mean in “spend the afternoon”?','use time doing something','pay money for an object','use up a water supply','spend the afternoon 指把时间用于某件事。',2,'meaning')]);
P('spending','Spending is formed from spend and -ing; as a noun it means money paid for goods, services, or public programs.',C('spending.s1','支出；花费','The city reduced spending on office renovations and redirected the money to repair two public clinics.','市政府削减了办公室翻修支出，并把资金转用于维修两家公立诊所。','The city reduced spending on renovations / and redirected the money / to repair clinics.','spending.s1 指为商品、服务或公共项目付出的钱。','削减翻修开支并转投诊所维修。'),M('The city’s spending on repairs was zero because it paid out a large sum for the clinic work.','The city spent money on the clinic repairs.','付出大笔资金就不是零支出。','meaning'),[q('What type of spending did the city reduce?','office renovation costs','clinic repair funds','museum grant income','市政府削减了办公室翻修支出。',1,'context'),q('Where did the redirected money go?','to repair two public clinics','to expand office renovations','to build a race stadium','资金转用于维修两家公立诊所。',1,'context'),q('What does spending mean as a noun?','money paid for goods, services, or programs','a period of dry weather','a person who writes speeches','spending 指支出的钱。',1,'meaning'),q('Which item counts as public spending?','government money used to repair a clinic','a private thought about a future purchase','unpaid time spent at home','政府用于维修诊所的资金属于 public spending。',1,'context')]);
P('spendthrift','Spendthrift combines spend and thrift; it means a person who wastes money, or wasteful spending habits.',C('spendthrift.s1','挥霍者；挥霍的','Although he earned a steady salary, the spendthrift bought another luxury watch each month and saved nothing.','尽管收入稳定，这名挥霍者每月又买一块奢华手表，一分钱也没存下。','The spendthrift bought a luxury watch each month / and saved / nothing.','spendthrift.s1 指浪费钱财的人，也可形容挥霍的习惯。','每月买奢侈品且毫无储蓄。'),M('The spendthrift saved nearly all his income and carefully avoided unnecessary purchases.','The spendthrift wasted money on repeated luxury purchases.','节俭储蓄与 spendthrift 的挥霍习惯相反。','meaning'),[q('What did the spendthrift buy each month?','another luxury watch','a new public clinic','a bag of spinach only','这名挥霍者每月又买一块奢华手表。',1,'context'),q('How much did he save?','nothing','nearly all his income','half of the museum grant','他没有存下任何钱。',1,'context'),q('What is a spendthrift?','someone who wastes money','someone who measures spectra','someone who writes a public speech','spendthrift 指挥霍钱财的人。',1,'meaning'),q('Which person is spendthrift?','one who repeatedly buys luxuries and saves nothing','one who budgets carefully and avoids extras','one who spends an afternoon cataloguing fossils','反复购买奢侈品却不储蓄的人是 spendthrift。',1,'context')]);
P('sperm','Sperm comes from Greek sperma, “seed”; it can mean a sperm cell or semen containing those cells.',C('sperm.s1','精子；精液','Under the microscope, the biologist observed a sperm cell moving through the prepared laboratory sample.','生物学家在显微镜下观察到一枚精子在制备好的实验样本中移动。','The biologist observed a sperm cell / under the microscope / in the sample.','sperm.s1 可指精子细胞，也可指含有这些细胞的精液。','显微镜下观察的是精子细胞。'),M('The biologist identified sperm in the sample as a mature red blood cell with no reproductive role.','The sample contained a reproductive cell observed under magnification.','红血细胞不是 sperm。','meaning'),[q('What did the biologist observe?','a sperm cell','a red blood cell','a spectral line','生物学家观察到一枚精子细胞。',1,'context'),q('How did the biologist view the cell?','under a microscope','through the stadium window','with a prism alone','生物学家通过显微镜观察样本。',1,'context'),q('What can sperm refer to?','a sperm cell or semen containing such cells','a male blood cell only','a spherical piece of metal','sperm 可指精子细胞或含精子的精液。',1,'meaning'),q('Which sample might contain sperm?','a reproductive-fluid specimen examined in a lab','a clean glass lens only','a public-spending record','实验室检查的生殖液体样本可能含 sperm。',1,'context')]);
P('spew','Spew is recorded in Middle English, perhaps imitative; it means pour out liquid, smoke, or words in a violent stream.',C('spew.s1','喷涌；吐出','The damaged pipe began to spew muddy water into the cellar after the storm.','暴风雨后，破裂的管道开始向地下室喷涌泥水。','The damaged pipe began to spew muddy water / into the cellar / after the storm.','spew.s1 指大量、猛烈地喷出液体、烟或话语。','管道破裂后泥水猛烈涌出。'),M('The broken pipe spewed water by keeping every drop safely inside and dry.','It forced a stream of muddy water into the cellar.','水留在管内而未涌出，与 spew 相反。','meaning'),[q('What did the damaged pipe spew?','muddy water','dry dust only','a short speech','破裂管道向外喷涌泥水。',1,'context'),q('Where did the water go?','into the cellar','onto the stadium seats','inside a microscope','泥水涌进地下室。',1,'context'),q('What does spew mean?','pour out forcefully in a stream','spend money carefully','watch without joining','spew 指猛烈喷涌或吐出。',1,'meaning'),q('Which pipe is spewing?','one blasting dirty water through a crack','one holding water without leaking','one carrying a dry cable','从裂口猛烈喷出脏水的管道在 spew。',1,'context')]);
P('sphere','Sphere comes from Greek sphaira, “ball”; it can mean a solid round shape or an area of activity, interest, or influence.',[C('sphere.s1','球体；球形','The glass artist formed a transparent sphere by blowing molten glass into a round mold.','玻璃工匠把熔融玻璃吹入圆模，制成一个透明球体。','The artist formed a glass sphere / by blowing molten glass / into a round mold.','sphere.s1 指像球一样的实心圆形物体。','玻璃被塑成圆球。'),C('sphere.s2','范围；领域；影响圈','The scientist’s work in the public sphere helped shape the debate about clean energy.','这位科学家在公共领域的工作影响了关于清洁能源的讨论。','The scientist’s work in the public sphere / helped shape / the energy debate.','sphere.s2 指某人的活动、兴趣或影响所及的领域。','科学家在公共事务领域参与讨论。')],M('The glass artist made a sphere by shaping the glass into a flat, square plate.','The artist blew the glass into a solid round form.','平面的方盘不是球体。','meaning'),[q('How did the artist make the sphere?','by blowing molten glass into a round mold','by cutting it into a square plate','by printing it on paper','工匠把熔融玻璃吹入圆模制成球体。',1,'context'),q('What debate did the scientist help shape?','the debate about clean energy','the price of theater tickets','the spelling of a surname','科学家影响了清洁能源讨论。',2,'context'),q('What is a sphere in the glass example?','a solid round shape','a public debate','a flat square plate','玻璃例句中的 sphere 指球体。',1,'meaning'),q('What does the public sphere mean?','an area of public activity or influence','a round ball used in glassblowing','a private household expense','public sphere 指公共活动或影响所及的领域。',1,'meaning')]);
P('spherical','Spherical is formed from sphere and -ical; it means shaped like a round ball or connected with the surface of a sphere.',[C('spherical.s1','球形的','The engineer tested a spherical buoy that could roll freely when waves pushed it across the water.','工程师测试了一个球形浮标，海浪推动时它能在水面上自由滚动。','The engineer tested a spherical buoy / that could roll freely / on the water.','spherical.s1 指形状像圆球的。','浮标可以滚动，说明外形近似球体。'),C('spherical.s2','球面的；天球的','The atlas uses spherical coordinates to describe locations on the globe’s curved surface.','这本地图集用球面坐标描述地球曲面上的位置。','The atlas uses spherical coordinates / to describe locations / on the globe’s curved surface.','spherical.s2 指与球体表面或天球相关的。','球面坐标用于标记曲面位置。')],M('The buoy was spherical although it had six flat square faces and could not roll.','Its round ball-like shape let the buoy roll across the water.','多面平板形且不能滚动不符合 spherical。','meaning'),[q('What could the spherical buoy do when pushed?','roll across the water','stay fixed like a square block','turn into a map atlas','球形浮标被推动时能在水面滚动。',1,'context'),q('What coordinates did the atlas use?','spherical coordinates','political party coordinates','speechwriter coordinates','地图集使用球面坐标描述地球曲面位置。',1,'context'),q('What does spherical mean about the buoy?','shaped like a round ball','made of six flat square faces','a field of public influence','spherical 描述浮标时指球形的。',1,'meaning'),q('What does spherical mean in spherical coordinates?','connected with a sphere’s curved surface','arranged in a flat square grid only','spoken aloud to an audience','球面坐标与球体曲面相关。',2,'meaning')]);
P('spheroid','Spheroid combines sphere and Greek -oeidēs, “resembling”; it means a body almost spherical but flattened or elongated.',C('spheroid.s1','类球体；旋转椭球','Earth is often modeled as a spheroid because rotation makes it slightly wider at the equator than at the poles.','地球常被建模为类球体，因为自转使它的赤道略宽于两极。','Earth is modeled as a spheroid / because it is wider / at the equator.','spheroid.s1 指接近球形但略扁或略长的物体。','赤道稍宽、两极稍扁。'),M('Earth is a spheroid because it is perfectly flat, with no curved dimensions at all.','Earth is nearly spherical but slightly flattened at the poles.','完全平坦的物体不是近似球形的 spheroid。','meaning'),[q('Where is Earth modeled as wider?','at the equator','at both poles only','on a perfectly flat edge','地球的赤道略宽于两极。',1,'context'),q('Why does Earth differ slightly from a perfect sphere?','its rotation makes it wider around the equator','it has six square faces','it contains no curved surface','地球自转使赤道区域略宽。',1,'context'),q('What is a spheroid?','a body nearly spherical but somewhat flattened or elongated','a perfectly flat plate','a short public speech','spheroid 指略扁或略长的近球形物体。',1,'meaning'),q('Which shape is a spheroid?','a ball slightly flattened at its poles','a perfect cube','a straight line with no width','两极略扁的球体是 spheroid。',1,'context')]);
P('spheroidal','Spheroidal is formed from spheroid and -al; it means having the form of a spheroid.',C('spheroidal.s1','近球形的','The seed has a spheroidal shape: almost round, but a little longer along one axis.','这颗种子呈近球形：整体接近圆形，但沿一个轴稍长。','The seed has a spheroidal shape / almost round / but longer along one axis.','spheroidal.s1 指具有略扁或略长的近球体形状。','种子近圆但一个方向更长。'),M('The seed was spheroidal because it had no rounded dimension and was a perfectly flat sheet.','It was nearly round but somewhat elongated along one axis.','平面薄片不是近球体形状。','meaning'),[q('How did the seed differ from a perfect sphere?','it was longer along one axis','it had six square faces','it was completely flat','种子沿一个轴略长，不是完全球形。',1,'context'),q('What overall shape did it have?','almost round','a flat rectangle','a sharp spike','种子整体接近圆形。',1,'context'),q('What does spheroidal mean?','having the form of an almost spherical body','having no curved dimension','connected with public debate','spheroidal 指具有近球体形状的。',1,'meaning'),q('Which object is spheroidal?','an almost round seed that is slightly elongated','a perfect square card','a long flat ribbon','略微拉长的近圆种子呈 spheroidal 形。',1,'context')]);
P('spice','Spice came through Old French from Latin species, “kind”; it can mean a strongly flavored plant product, added interest, or add flavor/excitement.',[C('spice.s1','香料；调味品','The cook ground a little spice into the lentil soup to give it a warm, fragrant flavor.','厨师把少许香料磨进扁豆汤里，让味道更温暖芬芳。','The cook ground spice into the soup / to give it / a warm flavor.','spice.s1 指用于给食物增添浓烈风味的种子、粉末或植物部分。','香料为汤增添香味。'),C('spice.s2','趣味；刺激','A short live demonstration added spice to an otherwise technical lecture.','一段现场演示为原本偏技术性的讲座增添了趣味。','A live demonstration added spice / to an otherwise technical lecture / for the audience.','spice.s2 比喻额外的兴奋感或趣味。','演示让讲座不再单调。'),C('spice.s3','加香料；使更有趣','The editor added a surprising anecdote to spice up the history chapter.','编辑加入一则出人意料的轶事，为历史章节增添趣味。','The editor added an anecdote / to spice up / the history chapter.','spice.s3 作动词，指给食物加香料或使故事更有趣。','轶事为章节添彩。')],M('The cook spiced the soup by removing every herb and leaving it completely flavorless.','The cook added an aromatic seasoning to give the soup a stronger flavor.','去掉调味料不会为汤增加 spice。','meaning'),[q('What did the cook add to the lentil soup?','a little spice','a metal sphere','a speech draft','厨师给扁豆汤加了少许香料。',1,'context'),q('What added spice to the lecture?','a live demonstration','a longer list of technical terms','a silent empty room','现场演示为讲座增添了趣味。',2,'context'),q('What did the editor add to spice up the chapter?','a surprising anecdote','a spelling error','a flat sphere','编辑加入了一则轶事让章节更有趣。',3,'context'),q('What does spice mean figuratively?','extra interest or excitement','a metal point in a plant','a written speech','spice 比喻额外的趣味或刺激。',2,'meaning')]);
P('spicy','Spicy is formed from spice and -y; it means strongly flavored with spices or, of stories/jokes, slightly shocking or sexually suggestive.',[C('spicy.s1','辛辣的；香料味浓的','The spicy curry made Arun reach for water after the chili and black pepper warmed his mouth.','咖喱里的辣椒和黑胡椒让阿伦感到口中灼热，伸手去拿水。','The spicy curry made Arun reach for water / after chili and pepper / warmed his mouth.','spicy.s1 指因辣椒、姜、胡椒等香料而味道浓烈或辛辣的。','辣椒和胡椒让咖喱辛辣。'),C('spicy.s2','（故事、笑话）带刺激意味的','The magazine rejected the spicy anecdote because its sexual jokes were unsuitable for the children’s issue.','杂志拒绝了这则带刺激意味的轶事，因为其中的性笑话不适合儿童刊物。','The magazine rejected the spicy anecdote / because its sexual jokes / were unsuitable for children.','spicy.s2 形容故事或笑话时，指略带令人震惊或色情暗示的内容。','轶事中的笑话不适合儿童。')],M('The spicy curry tasted bland because it contained no chili, ginger, pepper, or other seasoning.','The curry had a strong hot flavor from chili and pepper.','没有香料且味道清淡不符合 spicy。','meaning'),[q('Why did Arun reach for water?','the curry’s chili and pepper made his mouth hot','the curry was cold and tasteless','the magazine rejected the recipe','辣椒和胡椒让咖喱辛辣，阿伦去拿水。',1,'context'),q('Why did the magazine reject the anecdote?','its sexual jokes were unsuitable for a children’s issue','it had no characters','it included too much chili','其中的性笑话不适合儿童刊物。',2,'context'),q('What does spicy mean about the curry?','strongly flavored and hot from spices','sweet with no seasoning','shaped like a sphere','spicy 描述咖喱时指香料味浓并辛辣。',1,'meaning'),q('What does spicy mean about the anecdote?','slightly shocking or sexually suggestive','hot because it contains pepper','a report about a spectrum','spicy 描述轶事时指带刺激或性暗示。',1,'meaning')]);
P('spider','Spider comes from Old English spīthra, of uncertain origin; it means an eight-legged animal that spins silk, or an object with long thin legs.',[C('spider.s1','蜘蛛','A spider spun a web beneath the porch light, where it could catch moths attracted to the bulb.','一只蜘蛛在门廊灯下结网，可以捕捉被灯泡吸引来的飞蛾。','A spider spun a web / beneath the porch light / to catch moths.','spider.s1 指常结丝网捕捉昆虫的八足小动物。','蜘蛛在灯下结网捕食飞蛾。'),C('spider.s2','蜘蛛状支架；长腿支撑物','The mechanic placed a spider under the raised car to support it on several long metal legs.','修理工把一个蜘蛛状支架放在升起的汽车下方，用几根长金属腿支撑车辆。','The mechanic placed a spider under the car / to support it / on long metal legs.','spider.s2 可指有几条细长腿、形状像蜘蛛的物件或支架。','支架以多条长腿支撑车辆。')],M('The spider spun a web despite having no legs and being a metal stand under a car.','The eight-legged animal spun silk to catch insects near the light.','汽车支架不是会结网的动物。','meaning'),[q('Where did the spider build its web?','beneath the porch light','under the raised car','inside the magazine','蜘蛛在门廊灯下结网。',1,'context'),q('What did the mechanic use the spider for?','supporting a raised car','catching moths in a web','adding spice to soup','蜘蛛状支架用来支撑升起的汽车。',2,'context'),q('What is a spider in the porch example?','an eight-legged animal that spins silk','a metal car support','a moth drawn to light','门廊例句中的 spider 是结丝网的八足动物。',1,'meaning'),q('Why is the car support called a spider?','it has several long thin legs','it spins silk to catch insects','it has a round shell','支架有几条细长的腿，因此称为 spider。',2,'meaning')]);
P('spidery','Spidery is formed from spider and -y; it describes long, thin, angular limbs or handwriting that looks like them.',C('spidery.s1','细长如蛛的；蛛形的','Her spidery handwriting stretched across the narrow note in thin, angular letters.','她细长如蛛的笔迹用瘦长、棱角分明的字母写满了窄便条。','Her spidery handwriting stretched across the note / in thin / angular letters.','spidery.s1 指细长、棱角分明像蜘蛛腿的形状，也可形容这样的字迹。','字母细瘦而有棱角。'),M('His spidery handwriting used thick, rounded block letters that filled the page evenly.','The handwriting looked thin, angular, and spider-like.','粗圆的方块字与 spidery 的细长棱角特征相反。','meaning'),[q('What was spidery in the sentence?','the handwriting','the note’s paper color','the porch light','句子里的笔迹细长如蛛。',1,'context'),q('What did the letters look like?','thin and angular','thick and rounded','spherical and smooth','字母细瘦且棱角分明。',1,'context'),q('What does spidery mean?','long, thin, and angular like a spider’s legs','covered in sharp metal spikes','written in a short speech','spidery 指细长而棱角分明、像蜘蛛腿的。',1,'meaning'),q('Which handwriting is spidery?','narrow uneven letters with long thin strokes','bold round letters with thick strokes','perfectly spaced printed capitals','笔画细长、字形窄而不匀的字迹是 spidery。',1,'context')]);
P('spike','Spike may be related to Middle Dutch spīker, “ear of grain”; it can mean a pointed metal nail, a plant’s seed head, secretly add a substance, or rise sharply.',[C('spike.s1','尖钉；大钉','The carpenter drove a long spike through the beam to fasten it to the old post.','木匠把一根长尖钉穿过横梁，固定到旧立柱上。','The carpenter drove a spike through the beam / to fasten it / to the post.','spike.s1 指被钉入地面或硬材料的长而尖的金属件。','尖钉固定了横梁。'),C('spike.s2','穗状花序','Each barley spike held a row of small grains along the upper end of the stem.','每支大麦穗都在茎秆顶端排列着一串小籽粒。','Each barley spike held small grains / along the upper end / of the stem.','spike.s2 指大麦、小麦等植物上由许多籽粒组成的长穗。','穗状花序位于茎顶。'),C('spike.s3','暗中掺入','The bartender warned the staff never to spike a guest’s drink with alcohol or medicine.','酒保提醒员工，绝不可在客人的饮料中暗中掺入酒精或药物。','Staff must never spike a guest’s drink / with alcohol / or medicine.','spike.s3 作动词指未告知对方就把烈酒或其他物质加入饮料。','饮料不得被暗中添加物质。'),C('spike.s4','（数量）骤升','Online orders spiked after the company announced free delivery for the weekend.','公司宣布周末免运费后，线上订单量骤然上升。','Online orders spiked / after the company announced / free weekend delivery.','spike.s4 指数量或水平在短时间内急剧上升。','免运费公告后订单激增。')],M('Online orders spiked after the announcement by falling steadily to zero for the entire month.','Orders rose sharply for a short time after free delivery was announced.','持续降至零与 spike 所指的骤升相反。','meaning'),[q('What did the carpenter use to fasten the beam?','a long metal spike','a barley seed','a drink ingredient','木匠用长尖钉固定横梁。',1,'context'),q('Where were the barley grains arranged?','along the upper end of the stem','inside a metal nail','at the bottom of the beam','大麦籽粒排列在茎秆顶端的穗上。',2,'context'),q('What must staff never spike?','a guest’s drink without telling them','a beam with a nail','online orders with free delivery','员工不得在客人饮料中暗中加料。',3,'context'),q('What happened to online orders after the announcement?','they rose sharply','they fell to zero','they became barley spikes','免运费公告后线上订单量骤然上升。',4,'context')]);
P('spiky','Spiky is formed from spike and -y; it means covered with or shaped into sharp spikes.',C('spiky.s1','带刺的；尖刺状的','The spiky cactus was placed on a high shelf so the children would not brush against its sharp points.','带刺的仙人掌被放在高架上，以免孩子们碰到它的尖刺。','The spiky cactus was placed high / so children would not touch / its sharp points.','spiky.s1 指表面有尖刺或形状像尖刺的。','仙人掌尖刺需要避免接触。'),M('The cactus was spiky even though its surface was smooth, soft, and covered with no sharp points.','The cactus had sharp spikes on its surface.','没有尖刺的光滑表面不符合 spiky。','meaning'),[q('Where was the cactus placed?','on a high shelf','on the floor beside the children','inside a glass of water','带刺的仙人掌被放在高架上。',1,'context'),q('Why was it put there?','to keep children from touching its sharp points','to make it easier to water with a drink','to hide its smooth surface','这样能避免孩子们碰到尖刺。',1,'context'),q('What does spiky mean?','covered with sharp points','smooth and soft','a sharp rise in orders','spiky 指布满尖刺的。',1,'meaning'),q('Which plant is spiky?','a cactus with rigid points along its skin','a smooth leaf with no projections','a round seed with an even surface','表面有坚硬尖刺的仙人掌是 spiky。',1,'context')]);
P('spill','Spill comes from Old English spillan; it can mean make a liquid or small objects fall out, a crowd pour from a place, or a spill/fall.',[C('spill.s1','洒出；溢出','Nora spilled tea on the tablecloth when the train lurched around a bend.','火车转弯时突然晃动，诺拉把茶洒在了桌布上。','Nora spilled tea on the tablecloth / when the train / lurched around a bend.','spill.s1 可指使液体或小物从容器中洒出，也可指东西洒落。','列车晃动使茶洒出。'),C('spill.s2','涌出；涌入','After the final whistle, supporters spilled out of the stadium into the bright street.','终场哨响后，支持者从体育场涌到明亮的街道上。','Supporters spilled out of the stadium / after the final whistle / into the street.','spill.s2 指人群突然大量涌出某处。','观众在比赛结束后涌出体育场。'),C('spill.s3','洒出物；跌落','The oil spill near the harbor required a cleanup crew and warning barriers.','港口附近的漏油需要清理队伍和警示围栏。','The oil spill near the harbor / required a cleanup crew / and barriers.','spill.s3 作名词可指洒出的物质或跌倒。','港口漏油需要清理。')],M('Nora spilled tea by keeping every drop safely inside the cup during the train’s turn.','The tea fell out of the cup and spread across the cloth.','茶没有溢出就不能说 spilled。','meaning'),[q('What did Nora spill?','tea','oil from the harbor','a barley spike','诺拉把茶洒在桌布上。',1,'context'),q('Where did supporters spill after the whistle?','out of the stadium into the street','into the referee’s notebook','onto the harbor water','支持者从体育场涌到街道上。',2,'context'),q('What did the oil spill require?','a cleanup crew and warning barriers','a speechwriter and audience','a microscope and lens','港口漏油需要清理队伍和警示围栏。',3,'context'),q('What does spill mean in the stadium sentence?','a crowd pour out suddenly','liquid remain inside a cup','a sharp point on a cactus','人群例句中的 spill 指大量涌出。',2,'meaning')]);
P('spillage','Spillage is formed from spill and -age; it means an instance of liquid escaping from its container or the escaped liquid itself.',C('spillage.s1','溢出；泄漏物','The laboratory’s chemical spillage was contained with absorbent pads before it reached the drain.','实验室的化学品泄漏物在流入排水沟前就被吸收垫控制住了。','The chemical spillage was contained / with absorbent pads / before reaching the drain.','spillage.s1 指液体从容器中漏出这一事件，也可指漏出的液体。','吸收垫阻止泄漏物流入排水沟。'),M('The lab reported a spillage even though every chemical remained sealed inside its container.','A liquid escaped from its container and had to be contained.','液体没有漏出就不存在 spillage。','meaning'),[q('What was contained in the laboratory?','a chemical spillage','a crowd leaving the stadium','a dry barley spike','实验室控制住了化学品泄漏。',1,'context'),q('What kept it from reaching the drain?','absorbent pads','a speechwriter’s notes','a sharp cactus','吸收垫阻止泄漏物流入排水沟。',1,'context'),q('What is spillage?','an instance of liquid escaping or the escaped liquid','a person watching an event','a sudden rise in prices','spillage 指液体泄漏或漏出的液体。',1,'meaning'),q('Which event is a spillage?','oil leaking from a damaged drum onto the floor','a sealed drum staying intact','a crowd walking through a gate','油从破桶漏到地板上是 spillage。',1,'context')]);
P('spin','Spin comes from Old English spinnan; it can mean turn quickly, make thread/produce silk, give a biased account, or a turn/short drive/slanted presentation.',[C('spin.s1','旋转；使旋转','The child spun the top on the kitchen table and watched it wobble before falling.','孩子在厨房桌上旋转陀螺，看着它摇晃后倒下。','The child spun the top / on the kitchen table / until it wobbled.','spin.s1 指快速转动，或使物体快速转动。','孩子让陀螺旋转。'),C('spin.s2','纺线；吐丝结网','The silkworm can spin a fine thread around itself before it forms a cocoon.','蚕能在结茧前围着自己吐出细丝。','The silkworm can spin a fine thread / around itself / before forming a cocoon.','spin.s2 指扭转纤维制成线，也可指吐丝。','蚕吐丝结茧。'),C('spin.s3','有倾向地叙述；粉饰','The spokesperson tried to spin the delay as a careful safety review rather than a planning failure.','发言人试图把这次延误说成谨慎的安全审查，而非规划失误。','The spokesperson tried to spin the delay / as a safety review / instead of a planning failure.','spin.s3 指用偏向某一方的方式描述事件。','发言人对延误作有利于自己的解释。'),C('spin.s4','一圈；短途驾车；倾向性说法','We took a short spin around the block before deciding whether the used car handled well.','决定这辆二手车操控是否良好前，我们先绕街区短暂试驾了一圈。','We took a short spin around the block / before deciding / how the car handled.','spin.s4 名词可指快速旋转、短途兜风或带倾向的说法。','spin 指短途试驾。')],M('The spokesperson spun the delay by presenting it exactly as a failure and refusing to frame it positively.','The spokesperson framed the delay as a safety review to favor the project’s image.','有利于项目形象的包装才是这里的 spin。','meaning'),[q('What did the child spin?','a top','a silkworm cocoon','a used car','孩子在桌上旋转陀螺。',1,'context'),q('What does the silkworm spin?','a fine thread','a car around a block','a biased news account','蚕会吐出细丝。',2,'context'),q('How did the spokesperson spin the delay?','as a careful safety review','as a successful car test','as a silk cocoon','发言人把延误描述成谨慎的安全审查。',3,'context'),q('What did “a short spin” mean in the car example?','a brief drive around the block','a silkworm making thread','an account favoring one side','这里 short spin 指绕街区短暂开车。',4,'meaning')]);
P('spinach','Spinach came through Old French espinache from an Arabic/Persian source; it is a leafy green vegetable eaten raw or cooked.',C('spinach.s1','菠菜','The cook folded fresh spinach into the warm rice just before serving dinner.','厨师在晚餐上桌前，把新鲜菠菜拌进热米饭里。','The cook folded fresh spinach into the rice / just before serving / dinner.','spinach.s1 指可生吃或烹熟的绿叶蔬菜。','新鲜菠菜加入热米饭。'),M('The cook added spinach to the rice by removing every green leaf and serving only a metal spike.','Fresh leafy greens were folded into the warm rice.','金属尖钉不是菠菜。','meaning'),[q('What did the cook fold into the rice?','fresh spinach','a metal spike','a speech draft','厨师把新鲜菠菜拌进米饭。',1,'context'),q('When was it added?','just before serving dinner','after the guests left','before the rice was grown','菠菜在晚餐上桌前加入。',1,'context'),q('What is spinach?','a leafy green vegetable','a pointed metal nail','a spherical seed','spinach 指绿叶蔬菜菠菜。',1,'meaning'),q('Which dish contains spinach?','rice mixed with cooked leafy greens','a pot of plain water only','a dessert made from letters','拌入绿叶菜的米饭含有 spinach。',1,'context')]);
P('spinal','Spinal is formed from spine and -al; it means connected with the backbone or the spinal cord inside it.',C('spinal.s1','脊柱的；脊髓的','The doctor ordered spinal imaging after the cyclist reported numbness along the lower back.','骑行者报告下背部麻木后，医生安排了脊柱影像检查。','The doctor ordered spinal imaging / after the cyclist reported / lower-back numbness.','spinal.s1 指与脊柱或其中的脊髓有关。','影像检查针对背部和脊柱区域。'),M('The clinic called the scan spinal although it examined only the patient’s ankle bones.','The scan focused on the backbone and related structures.','只检查脚踝骨不属于脊柱检查。','meaning'),[q('What symptom did the cyclist report?','numbness along the lower back','a sore throat after a speech','a sharp spike in price','骑行者报告下背部麻木。',1,'context'),q('What did the doctor order?','spinal imaging','a spectroscopic food test','a stadium ticket','医生安排了脊柱影像检查。',1,'context'),q('What does spinal mean?','connected with the backbone or spinal cord','connected with a speech audience','related to a leafy vegetable','spinal 指与脊柱或脊髓有关。',1,'meaning'),q('Which procedure is spinal?','imaging the backbone after a back symptom','testing the leaves of spinach','measuring a runner’s speed','出现背部症状后对脊柱成像属于 spinal procedure。',1,'context')]);
P('spine','Spine comes through Old English from Latin spina, “thorn”; it can mean the backbone, a book’s binding edge, a plant’s point, or courage.',[C('spine.s1','脊柱；脊椎','The physiotherapist checked the curve of the runner’s spine after she reported pain between her shoulders.','跑者报告肩胛之间疼痛后，理疗师检查了她脊柱的弯曲情况。','The physiotherapist checked the runner’s spine / after she reported / pain between her shoulders.','spine.s1 指沿背部中央排列的脊椎骨。','检查针对背部的脊柱。'),C('spine.s2','书脊','The title is printed in gold on the spine of the atlas, so readers can find it on a crowded shelf.','地图集的书名用金字印在书脊上，读者在拥挤书架上也容易找到。','The title is printed on the atlas’s spine / so readers can find it / on the shelf.','spine.s2 指书本竖放时可见的封面窄侧边。','书脊上印着书名。'),C('spine.s3','刺；骨气','The cactus spine pierced the glove, while the volunteer showed spine by reporting the unsafe storage.','仙人掌刺穿了手套，而这名志愿者勇敢地报告了不安全的储存情况。','The cactus spine pierced the glove / while the volunteer showed spine / by reporting the hazard.','spine.s3 可指植物或动物的尖刺，也可比喻勇气。','同句分别使用尖刺与勇气义。')],M('The book’s spine was its printed title on the flat front cover, not the narrow binding edge.','The title on the narrow binding edge is the book’s spine.','封面正面不是书脊。','meaning'),[q('Where did the physiotherapist check the runner’s spine?','along her back','inside the atlas cover','on the cactus flower','理疗师检查了跑者背部的脊柱。',1,'context'),q('Where was the atlas title printed?','on its narrow binding edge','on the runner’s back','on a cactus spine','地图集标题印在书脊上。',2,'context'),q('What pierced the glove?','a cactus spine','the book’s title','the volunteer’s courage','刺穿手套的是仙人掌刺。',3,'context'),q('What does “showed spine” mean?','showed courage','showed a backbone on a scan','showed a book binding','showed spine 比喻表现出勇气。',3,'meaning')]);
P('spined','Spined is formed from spine and -ed; it means equipped with sharp spines or with a vertebral column.',C('spined.s1','有棘的；有脊椎的','The spined sea urchin stayed beneath a rock, its pointed structures warning divers not to touch it.','有棘海胆藏在岩石下，身上的尖刺提醒潜水员不要触碰。','The spined sea urchin stayed beneath a rock / with pointed structures / warning divers away.','spined.s1 指长有硬刺，也可指具有脊椎骨。','海胆表面有尖刺。'),M('The spined animal had no pointed structures or backbone and was a smooth ball of jelly.','The sea urchin was equipped with sharp spines.','光滑无刺且无骨骼不符合 spined。','meaning'),[q('Where did the spined sea urchin stay?','beneath a rock','inside a library shelf','on a train seat','海胆藏在岩石下。',1,'context'),q('What warned the divers away?','its pointed structures','its printed book title','its loud speech','海胆身上的尖刺提醒潜水员勿碰。',1,'context'),q('What does spined mean?','equipped with spines or a vertebral column','without a backbone','covered in smooth liquid','spined 指有刺或有脊椎的。',1,'meaning'),q('Which creature is spined?','a porcupine with sharp quills','a soft jelly ball with no hard parts','a flat sheet of paper','长有尖硬刺的豪猪是 spined。',1,'context')]);
P('spineless','Spineless combines spine and -less; figuratively it means too weak or cowardly to take a firm stand; literally, lacking a backbone.',[C('spineless.s1','懦弱的；没有骨气的','The spineless manager blamed a junior employee instead of admitting that he had approved the faulty plan.','懦弱的经理没有承认自己批准了错误计划，反而责怪一名下属。','The spineless manager blamed a junior / instead of admitting / his own approval.','spineless.s1 比喻缺乏勇气，不敢坚持立场或承担责任。','经理逃避责任。'),C('spineless.s2','无脊椎的','A jellyfish is spineless, so it has no spinal column even though its body can move through water.','水母是无脊椎动物，因此没有脊柱，尽管它能在水中移动。','A jellyfish is spineless / and has no spinal column / despite swimming through water.','spineless.s2 字面指没有脊椎骨的。','水母没有脊柱。')],M('The spineless manager took full responsibility and firmly defended the junior employee.','He avoided responsibility and blamed a junior worker instead.','勇敢担责与 figurative spineless 相反。','meaning'),[q('Who did the manager blame?','a junior employee','the jellyfish','the person who wrote the book','经理责怪了一名下属。',1,'context'),q('What does a jellyfish lack?','a spinal column','a way to move through water','a soft body','水母没有脊柱。',2,'context'),q('What does spineless mean about the manager?','too cowardly to take responsibility','having no vertebral bones','covered in pointed spines','spineless 描述经理时指懦弱、不敢担责。',1,'meaning'),q('What does spineless mean in the jellyfish example?','without a backbone','afraid to admit a mistake','quick to take a firm stand','水母例句里的 spineless 指没有脊椎。',1,'meaning')]);
P('spinet','Spinet came through French or Italian for a small keyboard instrument; it is a compact historical type of harpsichord.',C('spinet.s1','小型羽管键琴','The museum guide showed how the compact spinet fit into a town house where a full harpsichord would not.','博物馆讲解员展示了小型羽管键琴如何放进一座无法容纳大型羽管键琴的城市住宅。','The compact spinet fit in the town house / where a full harpsichord / would not.','spinet.s1 指一种体积较小的历史键盘乐器，属于小型羽管键琴。','体积小使它适合住宅。'),M('The museum called the spinet a compact keyboard instrument although it was a full-sized pipe organ filling the hall.','The spinet was a small harpsichord-like keyboard instrument.','占满大厅的大型管风琴不是小型羽管键琴。','meaning'),[q('Where could the compact instrument fit?','in the town house','only in a concert hall','beneath a cactus rock','小型琴能放进这座城市住宅。',1,'context'),q('What larger instrument would not fit?','a full harpsichord','a small spinet','a book with a narrow spine','大型羽管键琴无法放进那间住宅。',1,'context'),q('What is a spinet?','a compact historical keyboard instrument','a wind instrument with a long tube','a book’s binding edge','spinet 指小型历史键盘乐器。',1,'meaning'),q('Which object is a spinet?','a small harpsichord-style keyboard for a home','a full pipe organ filling a hall','a sea creature with no spine','适合家用的小型羽管键琴是 spinet。',1,'context')]);
P('spinneret','Spinneret combines spinner and -et; it names a spider’s silk-spinning organ or an industrial nozzle that forms filaments.',C('spinneret.s1','吐丝器；喷丝头','The spider’s spinneret released a silk thread that attached the web to the garden rail.','蜘蛛的吐丝器放出一根丝线，把蛛网固定在花园栏杆上。','The spinneret released a silk thread / that attached the web / to the rail.','spinneret.s1 可指蜘蛛吐丝器，也可指制造纤维丝的工业喷嘴。','蜘蛛用吐丝器放出丝线。'),M('The spider’s spinneret produced a stone bead rather than a strand of silk.','The spinneret released the silk thread used to anchor the web.','吐丝器产生丝线而不是石珠。','meaning'),[q('What did the spider’s spinneret release?','a silk thread','a book title','a sharp cactus spine','蜘蛛吐丝器放出一根丝线。',1,'context'),q('What did the thread attach?','the web to the garden rail','the rail to a keyboard','a jellyfish to a rock','丝线把蛛网固定到栏杆上。',1,'context'),q('What is a spinneret?','an organ or nozzle that forms filaments','a keyboard instrument','a vertebral column','spinneret 指吐丝器或制造细丝的喷嘴。',1,'meaning'),q('Which machine part is a spinneret?','a nozzle that extrudes thin synthetic fibers','a gear that winds a book spine','a blade that cuts cactus thorns','挤出合成纤维细丝的喷嘴是 spinneret。',1,'context')]);
P('spinning','Spinning is formed from spin and -ing; as a noun it means the craft or industry of turning fibers into thread or yarn.',C('spinning.s1','纺纱','The spinning mill turned cleaned cotton fibers into yarn for the local weaving workshop.','纺纱厂把清理后的棉纤维制成纱线，供当地织布作坊使用。','The spinning mill turned cotton fibers / into yarn / for the weaving workshop.','spinning.s1 指把纤维捻成线或纱的工艺、行业。','棉纤维被加工成纱线。'),M('The spinning mill made cotton yarn by keeping the fibers separate and never twisting them together.','The mill twisted cotton fibers into yarn.','纤维保持分散就没有完成纺纱。','meaning'),[q('What did the mill process?','cleaned cotton fibers','a sea urchin’s spines','a compact keyboard','纺纱厂加工棉纤维。',1,'context'),q('What did the fibers become?','yarn','a book spine','a pool of water','棉纤维被纺成纱线。',1,'context'),q('What is spinning?','making thread or yarn by twisting fibers','printing a title on a book','measuring light through a spectrum','spinning 指把纤维捻成线或纱。',1,'meaning'),q('Which workshop performs spinning?','one twisting cotton into yarn','one polishing a lens','one watching a performance','把棉纤维捻成纱线的作坊在 spinning。',1,'context')]);
P('spiny','Spiny is formed from spine and -y; it means having many sharp spines that can prick the skin.',C('spiny.s1','多刺的','The spiny branch snagged the gardener’s sleeve, so she put on thick gloves before trimming it.','多刺的树枝钩住了园丁的袖子，因此她修剪前戴上了厚手套。','The spiny branch snagged her sleeve / so she put on gloves / before trimming it.','spiny.s1 指长有许多容易刺伤皮肤的尖刺。','尖刺钩住衣袖。'),M('The spiny branch was harmless because it had no points and felt smooth against bare skin.','The branch had many sharp points that could prick her.','光滑无刺的树枝不是 spiny。','meaning'),[q('What did the spiny branch catch?','the gardener’s sleeve','the book’s title','a spinning wheel','多刺的树枝钩住了园丁的袖子。',1,'context'),q('What did she wear before trimming it?','thick gloves','a silk thread','a concert costume','园丁修剪树枝前戴上厚手套。',1,'context'),q('What does spiny mean?','having many sharp spines','having no backbone','spinning cotton into yarn','spiny 指有许多尖刺的。',1,'meaning'),q('Which plant is spiny?','a shrub whose sharp points can prick your hand','a soft smooth leaf with no points','a ball of cotton yarn','有尖刺会扎手的灌木是 spiny。',1,'context')]);
P('spiracle','Spiracle comes from Latin spiraculum, “breathing hole”; it is an external opening for breathing in insects or certain fish and whales.',C('spiracle.s1','呼吸孔','The biologist photographed a whale’s spiracle as it opened briefly at the surface to breathe.','鲸浮出水面短暂呼吸时，生物学家拍下了它的呼吸孔。','The biologist photographed the spiracle / as it opened / at the surface.','spiracle.s1 指昆虫气管系统或某些鱼类、鲸类的外部呼吸开口。','鲸在水面通过呼吸孔换气。'),M('The whale breathed through a spiracle located on its tail fin, far from its head.','The whale’s breathing opening was visible at the surface near the top of its head.','鲸的呼吸孔位于头顶附近而非尾鳍。','meaning'),[q('What did the biologist photograph?','the whale’s spiracle','the whale’s book spine','a spinning mill','生物学家拍摄了鲸的呼吸孔。',1,'context'),q('When did it open?','briefly at the surface','while buried deep in sand','only inside a museum','鲸浮出水面时呼吸孔短暂打开。',1,'context'),q('What is a spiracle?','an external breathing opening','a silk-producing organ in a spider','a small musical keyboard','spiracle 指外部呼吸孔。',1,'meaning'),q('Which animal structure can be a spiracle?','a whale’s breathing opening','a person’s bookbinding edge','a plant’s seed head','鲸用于呼吸的外部开口可称为 spiracle。',1,'context')]);
P('spiral','Spiral comes from Latin spiralis and Greek speira, “coil”; it can be a circling shape/path, a repeating rise or decline, or an adjective/verb for such movement.',[C('spiral.s1','螺旋；螺旋形','The shell’s spiral wound around a center and widened toward its outer edge.','贝壳的螺旋形绕着中心盘旋，向外缘逐渐变宽。','The shell’s spiral wound around a center / and widened / toward the edge.','spiral.s1 指围绕中心、同时向内外或上下延伸的形状或路线。','贝壳纹路绕中心盘旋。'),C('spiral.s2','螺旋式上升或恶化','Debt entered a downward spiral when late fees caused missed payments and still higher charges.','滞纳金导致错过还款、费用进一步增加，债务因此陷入恶性循环。','Debt entered a downward spiral / when late fees caused missed payments / and higher charges.','spiral.s2 指情况反复发展、持续变好或变坏的过程。','欠款和费用相互推高，形成恶性循环。'),C('spiral.s3','螺旋形的','The climber followed a spiral staircase that curled around the tower’s central column.','攀登者沿着绕塔楼中央柱盘旋的螺旋楼梯向上走。','The climber followed a spiral staircase / around the central column / of the tower.','spiral.s3 作形容词，指沿螺旋路线延伸或呈螺旋形的。','楼梯绕柱盘旋。'),C('spiral.s4','盘旋；持续升降','The loose kite began to spiral toward the field after its string slipped from the child’s hand.','风筝线从孩子手中滑脱后，松脱的风筝开始盘旋着落向田地。','The kite began to spiral toward the field / after its string / slipped away.','spiral.s4 作动词，指沿螺旋路线移动，也可指不断升降。','风筝盘旋着向下。')],M('The debt entered a downward spiral as fees disappeared, payments arrived on time, and the balance fell.','Late fees triggered missed payments and increasingly higher charges.','债务余额下降、费用消失不是恶化的循环。','meaning'),[q('What shape did the shell’s line make?','a spiral around a center','a straight line across the shell','a square frame','贝壳纹路围绕中心形成螺旋。',1,'context'),q('What caused debt to worsen?','late fees led to missed payments and higher charges','all payments arrived early','the debt was forgiven immediately','滞纳金导致漏还款和更多费用。',2,'context'),q('What did the climber follow?','a spiral staircase','a flat garden path','a book’s spine','攀登者沿螺旋楼梯前进。',3,'context'),q('What happened to the loose kite?','it spiraled toward the field','it stayed tied to the child’s hand','it formed a debt statement','风筝盘旋着落向田地。',4,'context')]);
P('spire','Spire is recorded in Middle English for a tall, pointed structure; its precise historical origin is uncertain.',[C('spire.s1','尖顶；塔尖','The church’s stone spire rose above the rooftops and served as a landmark for returning travelers.','教堂的石制尖塔高出屋顶，成为归来旅客辨认方向的地标。','The stone spire rose above the rooftops / and served / as a landmark.','spire.s1 指教堂塔楼顶部高而尖的部分。','教堂尖塔高耸成为地标。'),C('spire.s2','（山、树等）尖峰','A narrow rock spire stood above the ridge, outlined against the dawn sky.','一道狭长的岩石尖峰矗立在山脊上，在黎明的天空下显出轮廓。','A narrow rock spire stood above the ridge / outlined / against the dawn sky.','spire.s2 可指山、岩石或高树的尖顶。','岩峰从山脊上突出。')],M('The church spire was its broad, low foundation beneath the ground and could not be seen above the roofs.','The tall pointed tower top rose above the surrounding rooftops.','地下宽阔基础不是可见的尖塔顶部。','meaning'),[q('What rose above the rooftops?','the church’s stone spire','the underground foundation','the town’s river','教堂的石制尖塔高出屋顶。',1,'context'),q('What stood above the ridge?','a narrow rock spire','a flat lake','a church organ','狭长岩石尖峰矗立在山脊上。',2,'context'),q('What is a church spire?','the tall pointed top of a tower','the broad foundation below ground','a narrow book edge','教堂 spire 指塔楼顶部的尖塔。',1,'meaning'),q('What can a spire describe in a landscape?','a pointed top of rock or a tall tree','a round valley floor','a flat field with no rise','山岩或高树的尖顶也可称 spire。',2,'meaning')]);
P('spirit','Spirit comes from Latin spiritus, “breath”; it can mean the soul/mind, mood or attitude, a ghost, strong alcohol, or secretly remove someone/something.',[C('spirit.s1','精神；心灵；灵魂','The poem explores the human spirit by describing how hope survives during a long winter.','这首诗描写漫长冬季中的希望，探讨人的精神力量。','The poem explores the human spirit / by describing how hope / survives winter.','spirit.s1 指人的思想、情感或灵魂。','诗歌探讨内心的希望。'),C('spirit.s2','情绪；态度；志气','The volunteers kept their spirits high by singing while they repaired the storm-damaged shelter.','志愿者一边修复被风暴损坏的避难所，一边唱歌，让大家保持高昂情绪。','The volunteers kept their spirits high / by singing / during repairs.','spirit.s2 指人的情绪、态度或志气。','唱歌使志愿者士气高昂。'),C('spirit.s3','精灵；鬼魂','In the folktale, a spirit appeared beside the old bridge after midnight.','民间故事里，午夜过后一个鬼魂出现在老桥旁。','A spirit appeared beside the old bridge / after midnight / in the folktale.','spirit.s3 指超自然存在或死者的灵魂。','鬼魂出现在桥边。'),C('spirit.s4','烈酒','The customs form required travelers to declare any spirits they carried in their luggage.','海关表格要求旅客申报行李中携带的烈酒。','Travelers had to declare spirits / they carried / in their luggage.','spirit.s4 指威士忌、白兰地等烈性酒。','旅客需要申报烈酒。'),C('spirit.s5','迅速秘密带走','The guards spirited the witness away through a side entrance before the crowd gathered.','人群聚集前，警卫从侧门迅速秘密地带走了证人。','The guards spirited the witness away / through a side entrance / before the crowd gathered.','spirit.s5 作动词，指迅速而秘密地带走某人或某物。','证人被迅速带离现场。')],M('The volunteers kept their spirits high by refusing to sing, quitting the repair work, and discouraging one another.','They maintained morale by singing together while they worked.','相互打击并放弃工作不会振奋士气。','meaning'),[q('What did the poem explore?','the human spirit and hope','the price of strong alcohol','the church spire','诗歌探讨人的精神和希望。',1,'context'),q('How did volunteers keep their spirits high?','by singing during repairs','by declaring whisky at customs','by leaving the witness behind','志愿者唱歌以保持高昂情绪。',2,'context'),q('What appeared by the bridge in the folktale?','a spirit','a bottle of brandy','a stone tower top','民间故事里有鬼魂出现在桥边。',3,'context'),q('What did the guards do to the witness?','secretly took the witness away','served the witness a strong drink','asked the witness to sing','警卫迅速秘密地带走了证人。',5,'context')]);
P('spirited','Spirited is formed from spirit and -ed; it means lively and energetic, or determined and courageous in a difficult contest.',[C('spirited.s1','精神饱满的；活泼的','The spirited puppy raced around the garden and returned every ball the children tossed.','这只活泼的小狗在花园里奔跑，把孩子们扔出的每个球都叼回来。','The spirited puppy raced around the garden / and returned / every ball.','spirited.s1 指充满活力、热情或生气的。','小狗活跃地追球。'),C('spirited.s2','顽强的；勇敢的','The visitors mounted a spirited defense of their title even after two players were injured.','即使两名队员受伤，卫冕冠军仍进行了顽强的防守。','The visitors mounted a spirited defense / even after / two players were injured.','spirited.s2 指在困难情况下仍有决心和勇气地进行。','队伍在伤病后仍顽强防守。')],M('The spirited team gave up before the match began and showed no energy or determination.','The team defended its title energetically despite injuries.','赛前放弃且毫无活力，与 spirited 相反。','meaning'),[q('What did the spirited puppy do?','raced around and fetched balls','slept through the whole day','guarded a bridge at midnight','小狗活泼地奔跑并叼回球。',1,'context'),q('How did the visitors defend their title?','with determination despite injuries','by withdrawing before play','by declaring spirits at customs','队员受伤后仍顽强防守。',2,'context'),q('What does spirited mean about the puppy?','lively and energetic','quietly supernatural','short of courage','spirited 描述小狗时指活泼有活力。',1,'meaning'),q('What does spirited mean about the defense?','courageous and determined under difficulty','careless and unplanned','full of alcoholic drinks','spirited defense 指困难中顽强、勇敢的防守。',2,'meaning')]);
P('spiritedness','Spiritedness is formed from spirited and -ness; it means energy combined with a brave, determined temperament.',C('spiritedness.s1','生气；果敢','The captain’s spiritedness kept the crew focused when the storm damaged their radio.','风暴损坏无线电后，船长的果敢精神让船员仍能保持专注。','The captain’s spiritedness kept the crew focused / when the storm / damaged their radio.','spiritedness.s1 指充满活力、勇敢而坚定的性情。','船长在困难中鼓舞船员。'),M('The captain’s spiritedness made the crew give up at once and refuse to face the damaged radio.','The captain’s energy and determination kept the crew focused.','立刻放弃不是 spiritedness。','meaning'),[q('What damaged the crew’s radio?','the storm','a puppy’s ball','the captain’s speechwriter','风暴损坏了船员的无线电。',1,'context'),q('What effect did the captain’s spiritedness have?','it kept the crew focused','it made them abandon the vessel','it raised customs taxes','船长的果敢精神让船员保持专注。',1,'context'),q('What is spiritedness?','energetic, brave, determined temperament','a brief low mood','a shortness of breath','spiritedness 指充满活力、勇敢坚定的性情。',1,'meaning'),q('Which action shows spiritedness?','continuing a difficult rescue with courage and energy','quitting as soon as the radio fails','hiding a problem from the team','无线电故障后仍勇敢有力地继续救援体现 spiritedness。',1,'context')]);
P('spirits','Spirits is the plural of spirit; it can mean a person’s mood or strong alcoholic drinks such as whisky, vodka, or gin.',[C('spirits.s1','情绪；心境','A call from her family lifted Mei’s spirits after a tiring day at the hospital.','在医院忙碌一天后，家人的电话让梅的情绪振作起来。','The family call lifted Mei’s spirits / after a tiring day / at the hospital.','spirits.s1 指一个人在某时刻的心情或情绪，常见于 high/low/lift someone’s spirits。','家人来电改善了她的心情。'),C('spirits.s2','烈酒；酒精饮料','The shop keeps spirits such as gin and whisky behind the counter and checks customers’ ages.','商店把杜松子酒和威士忌等烈酒放在柜台后，并核查顾客年龄。','The shop keeps spirits such as gin and whisky / behind the counter / and checks ages.','spirits.s2 指威士忌、伏特加、杜松子酒等烈性酒的统称。','杜松子酒和威士忌属于烈酒。')],M('The call lifted Mei’s spirits by making her feel more discouraged and lonely than before.','The call improved Mei’s mood after a tiring day.','情绪更加低落不是 spirits 被振奋。','meaning'),[q('What lifted Mei’s spirits?','a call from her family','a bottle of gin','a damaged radio','家人的电话让梅振作起来。',1,'context'),q('Where did the shop keep spirits?','behind the counter','inside the hospital room','on the church spire','商店把烈酒放在柜台后。',2,'context'),q('What does spirits mean in the shop sentence?','strong alcoholic drinks','a person’s mood','supernatural beings','商店例句中的 spirits 指烈酒。',2,'meaning'),q('What does “lift someone’s spirits” mean?','improve that person’s mood','serve them whisky','take them away secretly','lift someone’s spirits 指让某人心情好起来。',1,'meaning')]);
P('spiritual','Spiritual is from Latin spiritualis, “of breathing/spirit”; it means connected with religion or the soul, or with inner thoughts rather than possessions.',[C('spiritual.s1','宗教的；与灵魂有关的','The retreat included spiritual practices such as quiet prayer and reflection on forgiveness.','静修活动包括安静祷告、思考宽恕等宗教和灵性实践。','The retreat included spiritual practices / such as quiet prayer / and reflection.','spiritual.s1 指与灵魂或宗教有关，而非身体或物质事物。','祷告和反思属于灵性活动。'),C('spiritual.s2','精神的；内心的','After losing her job, Lena said that support from friends mattered more to her spiritual well-being than expensive gifts.','失业后，莉娜说朋友的支持比昂贵礼物更能帮助她的内心健康。','Support from friends mattered to Lena’s spiritual well-being / more than / expensive gifts.','spiritual.s2 指与个人内心想法和情感有关，而非金钱或财物。','朋友支持有助于内在安定。')],M('The retreat was spiritual because it focused only on buying material goods and measuring their market value.','The retreat focused on prayer, reflection, and matters of the soul.','只关注物质购物不属于 spiritual。','meaning'),[q('What practices were part of the retreat?','quiet prayer and reflection','buying expensive furniture','repairing a spinal scan','静修活动包括安静祷告和反思。',1,'context'),q('What mattered more than expensive gifts to Lena?','support from friends','the price of her former office','a collection of spirits','朋友的支持比昂贵礼物更重要。',2,'context'),q('What does spiritual mean in the retreat example?','connected with religion or the soul','focused on money and possessions','relating to the backbone','这里 spiritual 指与宗教或灵魂有关。',1,'meaning'),q('What does spiritual well-being concern in Lena’s example?','inner thoughts and feelings','market prices of objects','a whale’s breathing opening','spiritual well-being 指内心想法和情感状态。',2,'meaning')]);
P('spit','Spit comes from Old English spittan; it can mean force liquid/food from the mouth, send out small bursts or speak sharply, light rain, or saliva/a roasting rod/a narrow point of land.',[C('spit.s1','吐；吐出','The child spit out the bitter medicine and asked for a glass of water.','孩子把苦药吐了出来，并要了一杯水。','The child spit out the bitter medicine / and asked / for water.','spit.s1 指把液体或食物从嘴里用力吐出。','孩子把难喝的药吐出。'),C('spit.s2','喷出；尖刻地说；下小雨','The damaged sprinkler spat water in short bursts while the mechanic complained about the broken valve.','损坏的洒水器一阵阵喷水，修理工则尖刻地抱怨坏掉的阀门。','The sprinkler spat water / in short bursts / as the mechanic complained.','spit.s2 可指断续喷出，也可指尖刻地说话或下小雨。','洒水器断续喷出水。'),C('spit.s3','唾沫；烤肉叉；岬','The cook turned the lamb on a spit over the fire while a rocky spit of land sheltered the small cove.','厨师在火上用烤肉叉转动羊肉，而一段岩石岬地为小海湾挡风。','The cook turned lamb on a spit / while a rocky spit / sheltered the cove.','spit.s3 可指唾液、烤肉叉或伸入水中的狭长陆地。','同一句用到烤肉叉和岬地义。')],M('The child spit out the medicine by swallowing it without letting any food or liquid leave the mouth.','The child forced the bitter medicine back out of the mouth.','把药吞下而未吐出与 spit out 相反。','meaning'),[q('What did the child spit out?','the bitter medicine','a roast lamb on a rod','a narrow point of land','孩子把苦药吐了出来。',1,'context'),q('What did the damaged sprinkler do?','spat water in short bursts','swallowed the medicine','sheltered a cove','洒水器一阵阵喷出水。',2,'context'),q('What did the cook turn over the fire?','lamb on a roasting spit','a sea cove','the child’s medicine','厨师在烤肉叉上转动羊肉。',3,'context'),q('What is a rocky spit of land?','a narrow projection of land into water','saliva from a mouth','a metal rod for roasting meat','rocky spit of land 指伸入水中的狭长陆地。',3,'meaning')]);
P('spit out','Spit out is a phrasal verb: it means force food/liquid from the mouth or lungs, or say something quickly and angrily.',[C('spit out.s1','吐出；咳出','The toddler spit out the seed after tasting the sour plum.','尝到酸梅后，幼儿把果核吐了出来。','The toddler spit out the seed / after tasting / the sour plum.','spit out.s1 指把食物、液体或异物从口中或肺部用力排出。','幼儿把果核吐出。'),C('spit out.s2','脱口而出；尖刻地说','“That is not what I said,” the witness spit out angrily before the judge interrupted.','法官打断前，证人愤怒地脱口说道：“我不是这么说的。”','The witness spit out the words angrily / before the judge / interrupted.','spit out.s2 指迅速、愤怒地说出某句话。','证人带怒气地脱口而出。')],M('The toddler spit out the seed by swallowing it and keeping it inside the mouth.','The toddler forced the seed out of the mouth.','吞下并留在嘴里不是吐出。','meaning'),[q('What did the toddler spit out?','the plum seed','the judge’s order','a spiral staircase','幼儿把酸梅果核吐出来。',1,'context'),q('How did the witness say the words?','angrily and abruptly','quietly after careful rehearsal','through a phone text','证人愤怒地脱口说出那句话。',2,'context'),q('What does spit out mean in the plum example?','force an object from the mouth','say something in a calm tone','send out small bursts of rain','果梅例句中的 spit out 指把东西从嘴里吐出。',1,'meaning'),q('What does spit out mean in the witness example?','say something quickly and angrily','swallow a seed','use a roasting rod','证人例句中的 spit out 指愤怒地脱口而出。',2,'meaning')]);
P('spite','Spite came through Old French despit; it can mean a wish to hurt someone, deliberately annoy them, or occur despite a difficulty in “in spite of.”',[C('spite.s1','恶意；怨恨','She refused to share the false rumor out of spite, hoping it would embarrass her former teammate.','她出于怨恨拒绝澄清谣言，希望让前队友难堪。','She repeated the false rumor out of spite / hoping to embarrass / her former teammate.','spite.s1 指想伤害、烦扰或使人不快的恶意。','她希望谣言伤害前队友。'),C('spite.s2','故意刁难；使恼怒','The landlord spitefully turned off the hallway lights to annoy the tenant who had complained.','房东故意关掉走廊灯，想惹恼提出投诉的房客。','The landlord turned off the lights out of spite / to annoy / the tenant.','spite.s2 作动词，指故意伤害或惹恼某人。','关灯是为了报复投诉者。'),C('spite.s3','尽管；不顾','In spite of the heavy rain, the outdoor ceremony continued under the covered stage.','尽管下着大雨，户外仪式仍在有顶舞台下继续进行。','In spite of the heavy rain / the outdoor ceremony / continued.','spite.s3 用于 in spite of，表示尽管有某种困难，事情仍发生。','大雨没有阻止仪式。')],M('The landlord acted out of spite by carefully helping the tenant and trying to make the complaint easier to resolve.','The landlord deliberately annoyed the tenant in retaliation for the complaint.','主动帮助对方解决问题不是恶意报复。','meaning'),[q('Why did she repeat the false rumor?','out of spite toward her former teammate','to help the teammate’s reputation','because it was a verified report','她出于怨恨传播谣言，希望让前队友难堪。',1,'context'),q('Why did the landlord turn off the lights?','to annoy the tenant who complained','to help the tenant see better','because the ceremony needed rain','房东关灯是为了惹恼投诉的房客。',2,'context'),q('What happened in spite of the rain?','the outdoor ceremony continued','the stage disappeared','the guests went home before arriving','尽管下雨，户外仪式仍继续。',3,'context'),q('What does “in spite of” mean?','despite a difficulty','because someone wants revenge','with no exception to a rule','in spite of 表示尽管有困难。',3,'meaning')]);
P('spiteful','Spiteful is formed from spite and -ful; it means eager to hurt, annoy, or embarrass someone because of a grudge, or mean over trivial matters.',[C('spiteful.s1','恶意的；怀恨的','A spiteful former partner posted private messages online to embarrass Jo after their disagreement.','发生争执后，一位心怀恶意的前伴侣把私人信息发到网上，想让乔难堪。','A spiteful former partner posted private messages / to embarrass Jo / after the disagreement.','spiteful.s1 指因怨恨而想伤害、惹恼或羞辱他人的。','泄露私人信息是为了羞辱对方。'),C('spiteful.s2','刻薄的；斤斤计较的','His spiteful complaint about a two-minute delay made the otherwise friendly meeting uncomfortable.','他为两分钟的延误刻薄抱怨，让原本友好的会议变得尴尬。','His spiteful complaint about a two-minute delay / made the meeting / uncomfortable.','spiteful.s2 可指对无关紧要的小事表现得刻薄、心胸狭窄。','为微小延误刻薄抱怨。')],M('The spiteful partner protected Jo’s privacy and apologized sincerely after the disagreement.','The former partner shared private messages to embarrass Jo.','保护隐私并真诚道歉不是 spiteful。','meaning'),[q('What did the spiteful former partner post?','Jo’s private messages','a public weather report','a book’s title','前伴侣把乔的私人信息发到网上。',1,'context'),q('What small delay drew the spiteful complaint?','two minutes','two months','one year','抱怨针对两分钟的延误。',1,'context'),q('What does spiteful mean in the first example?','wanting to hurt or embarrass someone','showing calm satisfaction','moving without energy','前例中的 spiteful 指想伤害或羞辱别人。',1,'meaning'),q('What does spiteful mean about the complaint?','mean over an unimportant matter','a fair warning about a serious danger','a cheerful welcome','此处 spiteful 指为小事刻薄、心胸狭窄。',2,'meaning')]);
P('splash','Splash may be imitative of the sound of liquid striking a surface; it can mean send liquid in drops, feature something prominently, or the sound/patch/small amount.',[C('splash.s1','溅；泼；溅湿','The canoe paddle splashed cold lake water onto the children as they crossed the bay.','独木舟划过海湾时，船桨把冰凉的湖水溅到孩子们身上。','The paddle splashed water onto the children / as they crossed / the bay.','splash.s1 指使液体飞溅成水滴，也可指把人或物溅湿。','船桨使水滴飞到孩子身上。'),C('splash.s2','显眼报道；醒目刊登','The newspaper splashed the election result across its front page in a bold headline.','报纸用醒目标题把选举结果刊登在头版显眼位置。','The newspaper splashed the result across its front page / in a bold / headline.','splash.s2 作动词，指以非常显眼的方式刊登新闻或图片。','结果被放在头版突出位置。'),C('splash.s3','溅泼声；色块；少量','A splash of yellow paint brightened the gray mural, while a splash sounded in the fountain below.','一抹黄色颜料让灰色壁画明亮起来，下面的喷泉同时传来一声水花声。','A splash of yellow paint brightened the mural / while a splash sounded / in the fountain.','splash.s3 作名词可指液体撞击声、色块或少量液体。','句子展示色块和溅水声。')],M('The paddle splashed the children by keeping every drop of water inside the canoe.','The paddle sent droplets of lake water onto the children.','水没有飞溅出来就没有 splash。','meaning'),[q('What splashed water onto the children?','the canoe paddle','the newspaper headline','a dry mural brush','船桨把湖水溅到孩子身上。',1,'context'),q('Where did the newspaper put the result?','across the front page','in a hidden archive only','on the canoe paddle','报纸把结果醒目刊登在头版。',2,'context'),q('What brightened the mural?','a splash of yellow paint','a quiet speech','a wet newspaper headline','一抹黄色颜料让壁画明亮起来。',3,'context'),q('What does splash mean in “a splash sounded”?','the sound of liquid striking a surface','a prominent newspaper headline','a large amount of dry paint','a splash sounded 指液体撞击表面的水声。',3,'meaning')]);
P('splatter','Splatter is imitative in origin; it means cause liquid to fly in drops, or a spot left by liquid flung onto a surface.',[C('splatter.s1','溅；泼洒','The bicycle tire splattered muddy water across the shop window as it passed the puddle.','自行车轮经过水坑时，把泥水溅到了商店橱窗上。','The bicycle tire splattered muddy water / across the shop window / beside a puddle.','splatter.s1 指使液体分散成水滴飞落到表面上。','车轮把泥水溅到窗上。'),C('splatter.s2','溅出的污迹','A brown splatter on the wall showed where the leaking pipe had sprayed dirty water.','墙上的褐色溅斑显示，漏水管曾把脏水喷到那里。','A brown splatter on the wall / showed where / the pipe leaked.','splatter.s2 作名词，指液体飞溅后留下的斑点或污迹。','污迹来自漏管喷出的水。')],M('The bicycle tire splattered the window by keeping all muddy water inside the tire.','It flung droplets of muddy water across the glass.','水没有飞出就不会溅到玻璃上。','meaning'),[q('What did the bicycle tire splatter?','muddy water','a speech draft','clean dry sand','车轮把泥水溅到了橱窗上。',1,'context'),q('What did the brown splatter indicate?','a leaking pipe had sprayed dirty water','a clean window had been polished','the bicycle had a new tire','墙上污斑显示管子曾漏水。',2,'context'),q('What does splatter mean as a verb?','send liquid flying in drops','keep liquid sealed in a container','divide work among people','splatter 作动词指使液体飞溅。',1,'meaning'),q('What is a splatter on a wall?','a mark left by flung liquid','a clean dry patch with no mark','a bone used to support a limb','墙上的 splatter 是液体飞溅留下的斑迹。',2,'meaning')]);
P('spleen','Spleen comes from Greek splēn; it names an abdominal organ, and figuratively can mean angry temper or resentment.',[C('spleen.s1','脾脏','The scan showed that the patient’s spleen was enlarged, so the doctor ordered further blood tests.','扫描显示病人的脾脏肿大，因此医生安排了进一步血液检查。','The scan showed an enlarged spleen / so the doctor / ordered blood tests.','spleen.s1 指腹部过滤血液并帮助抵抗感染的器官。','影像检查发现脾脏肿大。'),C('spleen.s2','怒气；怨恨','In a letter full of spleen, the columnist attacked the officials who had ignored residents’ warnings.','专栏作者在一封充满愤怒的信中，抨击了无视居民警告的官员。','The columnist wrote with spleen / attacking officials / who ignored warnings.','spleen.s2 指愤怒或怨恨，尤指把坏脾气表达出来。','作者愤怒地指责官员。')],M('The scan identified the spleen as a bone in the leg that pumps air into the lungs.','The spleen is an abdominal organ involved in filtering blood and immunity.','脾脏不是腿骨或肺部器官。','meaning'),[q('What did the scan show?','the patient’s spleen was enlarged','the patient’s ankle was broken','the columnist had written a letter','扫描显示病人的脾脏肿大。',1,'context'),q('What filled the columnist’s letter?','anger at officials who ignored warnings','a calm report on a blood test','a sponsorship offer','这封信充满对官员的愤怒。',2,'context'),q('What is the spleen in the medical example?','an abdominal organ','a bone in the leg','a breathing tube in an insect','脾脏是腹部器官。',1,'meaning'),q('What does spleen mean figuratively?','expressed anger or resentment','a test result showing organ size','a cheerful, energetic mood','spleen 可比喻表达出来的愤怒或怨恨。',2,'meaning')]);
P('splendid','Splendid comes through French from Latin splendidus, “bright”; it can mean excellent or magnificent to look at.',[C('splendid.s1','极好的；出色的','The mechanic did a splendid job repairing the old theater’s lighting system before opening night.','机械师在首演之夜前出色地修好了老剧院的照明系统。','The mechanic did a splendid job / repairing the theater lights / before opening night.','splendid.s1 指质量极好、表现出色的。','维修工作完成得非常好。'),C('splendid.s2','壮丽的；辉煌的','From the hilltop, the visitors saw a splendid view of the river and its bridges at sunset.','游客从山顶看到了日落时河流与桥梁交相辉映的壮丽景色。','The visitors saw a splendid view / of the river and bridges / at sunset.','splendid.s2 指外观宏伟、令人赞叹的。','日落景色十分壮丽。')],M('The mechanic did a splendid job by leaving the lights broken and failing to repair the theater.','The mechanic repaired the lighting system very well before opening night.','修不好照明系统不能称为出色工作。','meaning'),[q('What did the mechanic repair?','the theater’s lighting system','the river bridges','a patient’s spleen','机械师修好了剧院的照明系统。',1,'context'),q('When was the repair completed?','before opening night','after the theater closed forever','during a medical scan','照明系统在首演前修好。',1,'context'),q('What does splendid mean about the mechanic’s job?','excellent','enlarged','angry','splendid 描述工作时指出色的。',1,'meaning'),q('What did visitors see from the hilltop?','a magnificent sunset view of the river and bridges','a broken lighting switch','a small stain on a wall','游客从山顶看到了壮丽的日落河景。',2,'context')]);
P('splendor','Splendor comes from Latin splendor, “brightness”; it means great beauty with an impressive appearance or a magnificent sight.',[C('splendor.s1','壮丽；辉煌','The palace’s splendor came from its marble halls, painted ceilings, and carefully restored mosaics.','宫殿的大理石大厅、彩绘天花板和精心修复的马赛克共同展现出辉煌气派。','The palace’s splendor came from / its marble halls / and restored mosaics.','splendor.s1 指令人赞叹的宏伟美丽和外观。','建筑装饰共同形成辉煌气象。'),C('splendor.s2','壮丽景象；奇观','The guide stopped the bus so visitors could admire the splendor of the canyon at sunrise.','导游停下巴士，让游客欣赏日出时峡谷的壮丽景色。','The guide stopped the bus / so visitors could admire / the canyon’s splendor.','splendor.s2 指外观宏伟壮丽的地点、建筑或自然景色。','日出峡谷是一处壮丽景观。')],M('The palace’s splendor came from bare walls, cracked floors, and missing decorations.','Its impressive halls and restored mosaics gave the palace great beauty.','破败空荡的内部不会呈现 splendid splendor。','meaning'),[q('What details contributed to the palace’s splendor?','marble halls and restored mosaics','a broken pipe and muddy water','a plain empty room','宫殿的大理石大厅和马赛克展现辉煌。',1,'context'),q('When did visitors admire the canyon?','at sunrise','after midnight in a closed hall','during a spelling test','游客在日出时欣赏峡谷。',2,'context'),q('What does splendor mean about the palace?','great beauty and impressive appearance','a blood-filtering organ','a sharp broken fragment','splendor 描述宫殿时指宏伟美丽。',1,'meaning'),q('What is a natural splendor?','a magnificent canyon view at sunrise','a small brown water stain','an angry letter','日出时壮丽的峡谷景色是一种 natural splendor。',2,'meaning')]);
P('splint','Splint is from Middle English splente, “thin piece of wood”; it means a rigid piece fixed along a limb to keep a fracture still.',C('splint.s1','夹板','The medic secured a lightweight splint along the skier’s forearm until the clinic could examine the fracture.','医护人员把轻便夹板固定在滑雪者前臂旁，直到诊所检查骨折。','The medic secured a splint along the forearm / until the clinic / examined the fracture.','splint.s1 指固定在肢体旁、防止骨折部位移动的硬质支撑物。','夹板让前臂保持稳定。'),M('The medic used a splint to keep the broken forearm bending freely during the trip.','The splint held the injured limb still until medical care was available.','夹板的用途是限制移动，而非让骨折处自由弯曲。','meaning'),[q('Where did the medic secure the splint?','along the skier’s forearm','around the skier’s neck','under the theater stage','夹板固定在滑雪者前臂旁。',1,'context'),q('How long was it kept in place?','until the clinic could examine the fracture','only until the skier began moving it','for several years after healing','夹板一直固定到诊所检查骨折。',1,'context'),q('What is a splint used for?','keeping a fractured limb from moving','covering a wall with paint','stopping a liquid spill','splint 用于固定骨折肢体。',1,'meaning'),q('Which item is a splint?','a rigid support strapped beside an injured arm','a soft towel used to dry hands','a small patch of colored ink','绑在受伤手臂旁的硬支撑物是 splint。',1,'context')]);
P('splinter','Splinter comes from Middle Dutch splinter; it means a sharp sliver broken from a hard material, or the division of a group into smaller parts.',C('splinter.s1','尖碎片；分裂','A splinter from the broken crate lodged in the worker’s glove, so she removed it with tweezers.','破木箱上的一根尖碎片扎进工人的手套，她用镊子把它取了出来。','A splinter from the crate lodged in the glove / so she removed it / with tweezers.','splinter.s1 指从木头、玻璃等硬物上断下的尖细碎片，也可指团体分裂。','木屑碎片扎进手套。'),M('The splinter was a smooth, unbroken sheet that could not pierce a glove.','A sharp sliver broke off the crate and lodged in the glove.','完整光滑的板片不是尖碎片。','meaning'),[q('Where did the splinter lodge?','in the worker’s glove','inside the clinic’s computer','on the canyon floor','木箱碎片扎进了工人的手套。',1,'context'),q('How did she remove it?','with tweezers','by swallowing it','by painting over it','她用镊子取出了碎片。',1,'context'),q('What is a splinter?','a sharp sliver broken from a hard material','a soft piece of unbroken cloth','an official public statement','splinter 指硬物断下的尖碎片。',1,'meaning'),q('What can “a party splinter” mean?','a group breaking into smaller factions','a wooden fragment in a glove','a medical support for a limb','a party splinter 可指政党分裂成小派别。',1,'meaning')]);
P('split','Split is recorded from Middle English; it can mean break into parts, divide a cost/work/share, or a crack, disagreement, or share.',[C('split.s1','劈开；撕裂；分裂','The dry log split down the middle when the woodcutter struck it with an axe.','伐木工用斧头敲击后，干木头从中间裂开。','The dry log split down the middle / when the woodcutter / struck it with an axe.','split.s1 可指分成两块或多块，也可指使某物裂开。','木头被斧头劈开。'),C('split.s2','分担；分摊；分享','The roommates agreed to split the electricity bill equally at the end of each month.','室友们同意每月底平摊电费。','The roommates agreed to split the electricity bill / equally / each month.','split.s2 指把钱、工作或食物分给几个人。','室友平分账单。'),C('split.s3','裂缝；分歧；份额','A split in the old leather seat widened after years of use.','旧皮座椅上的裂缝经过多年使用后变宽了。','A split in the old leather seat / widened / after years of use.','split.s3 作名词可指长裂缝、意见分歧或分得的一份。','座椅上的裂缝扩大。')],M('The roommates split the bill by making one person pay the whole amount and giving the others no share.','They divided the electricity cost equally among themselves.','一人承担全部费用不是均分账单。','meaning'),[q('How did the log split?','down the middle','into a perfect sphere','along a book’s spine','木头从中间裂开。',1,'context'),q('How did the roommates split the bill?','equally among themselves','one person paid it all','they left it unpaid','室友们平摊电费。',2,'context'),q('What widened in the leather seat?','a crack','the monthly electricity bill','the log’s weight','座椅上的裂缝变宽了。',3,'context'),q('What does split mean in the roommates’ sentence?','divide the cost among people','break a log into pieces','a crack in leather','室友例句中的 split 指分摊费用。',1,'meaning')]);
P('split up','Split up combines split and up; it can mean end a romantic relationship/marriage or divide a group or thing into smaller units.',[C('split up.s1','分手；分居','After months of trying to repair the relationship, the couple decided to split up and live separately.','尝试修复关系数月后，这对伴侣决定分手并分开生活。','The couple decided to split up / after months of effort / and live separately.','split up.s1 指结束恋爱关系或婚姻。','伴侣决定结束关系并分开居住。'),C('split up.s2','拆分；分成小组','The teacher split up the class into four teams to prepare different parts of the exhibition.','老师把全班分成四个小组，分别准备展览的不同部分。','The teacher split up the class / into four teams / for the exhibition.','split up.s2 指把较大的群体或整体分成若干较小部分。','一个班被分成四队。')],M('The teacher split up the class into one single undivided team of every student.','The teacher divided the class into four smaller teams.','未分成小组与 split up 相反。','meaning'),[q('What did the couple decide after months of effort?','to end the relationship and live separately','to marry for the first time','to form four exhibition teams','伴侣决定分手并分开生活。',1,'context'),q('Into how many teams did the teacher split the class?','four','one undivided group','twelve married couples','老师把全班分成四队。',2,'context'),q('What does split up mean about the couple?','end a romantic relationship','divide a class into teams','share a monthly bill','情侣例句中的 split up 指分手。',1,'meaning'),q('What does split up mean about the class?','divide it into smaller groups','end a marriage','make one team larger without division','老师例句中的 split up 指把大组拆成小组。',2,'meaning')]);
P('splotch','Splotch is probably imitative in origin; it means a large, uneven patch of color, ink, or dirt.',C('splotch.s1','不规则污斑','A purple splotch of paint spread across the poster when the wet brush slipped from Kai’s hand.','湿画笔从凯手中滑落时，紫色颜料在海报上洇开成一大块不规则污斑。','A purple splotch of paint spread across the poster / when the brush / slipped.','splotch.s1 指较大且形状不规则的颜色、墨水或污物斑块。','颜料形成不规则色块。'),M('The poster had a splotch that was a perfectly straight, narrow, clean line with no colored patch.','The spilled paint made a large uneven purple mark.','整齐细线不是不规则色斑。','meaning'),[q('What color was the splotch?','purple','green','transparent','海报上出现紫色污斑。',1,'context'),q('What caused it?','the wet brush slipped','the paint stayed sealed in its jar','the poster was folded neatly','湿画笔滑落导致颜料洇开。',1,'context'),q('What is a splotch?','a large uneven patch of color or dirt','a narrow straight clean line','a bone support for a fracture','splotch 指大块不规则色斑或污迹。',1,'meaning'),q('Which mark is a splotch?','an irregular blot of ink on a page','a ruler-straight pencil line','a blank clean sheet','页面上的不规则墨团是 splotch。',1,'context')]);
P('spoil','Spoil comes from Old French espoillier, “to strip”; it can mean ruin pleasure/value, overindulge a child, food go bad, or stolen/war goods.',[C('spoil.s1','毁掉；破坏；扫兴','A loud construction drill spoiled the outdoor concert by drowning out the quiet acoustic songs.','刺耳的施工钻机声盖过了轻柔的原声歌曲，毁掉了户外音乐会的气氛。','A loud drill spoiled the concert / by drowning out / the acoustic songs.','spoil.s1 指严重损害某物价值或乐趣。','噪声破坏了音乐会的欣赏效果。'),C('spoil.s2','宠坏；溺爱','If the grandparents spoil the child with a new toy after every tantrum, she may learn to demand more.','如果祖父母每次孩子发脾气后都送新玩具，孩子可能学会提出更多要求。','The grandparents may spoil the child / by giving a toy / after every tantrum.','spoil.s2 指过度满足孩子，使其行为变差。','发脾气就获新玩具可能助长任性。'),C('spoil.s3','（食物）变坏','The fish spoiled after the refrigerator lost power overnight.','冰箱夜间断电后，鱼变质了。','The fish spoiled / after the refrigerator / lost power overnight.','spoil.s3 指食物变得不适合食用。','断电导致鱼变坏。'),C('spoil.s4','战利品；赃物','The museum returned the stolen spoils that had been taken from the village during the war.','博物馆归还了战争期间从村庄掠走的赃物。','The museum returned stolen spoils / taken from the village / during the war.','spoil.s4 作名词复数可指战争中强取的战利品或赃物。','物品是战争期间被掠走的。')],M('The loud drill spoiled the concert by making every song clearer and more enjoyable for the audience.','The drill drowned out the music and ruined the audience’s enjoyment.','增强欣赏效果不是 spoil。','meaning'),[q('What spoiled the outdoor concert?','a loud construction drill','a quiet acoustic song','the museum’s written report','施工钻机声盖过歌曲，破坏了音乐会。',1,'context'),q('When might grandparents spoil a child?','by giving a toy after every tantrum','by setting fair limits consistently','by letting the child help clean','每次发脾气都给玩具可能宠坏孩子。',2,'context'),q('Why did the fish spoil?','the refrigerator lost power overnight','the museum returned it','the concert was outdoors','冰箱夜间断电后鱼变质了。',3,'context'),q('What were the stolen spoils?','goods taken from the village during the war','fresh fish kept in a working refrigerator','toys given after a tantrum','战争期间从村庄掠走的物品是 spoils。',4,'meaning')]);
P('spoilage','Spoilage is formed from spoil and -age; it means the process of food going bad or the amount lost through deterioration.',C('spoilage.s1','变质；腐败损耗','The grocer reduced spoilage by keeping dairy products cold and checking their dates each morning.','杂货商通过冷藏乳制品并每天早上检查日期，减少了变质损耗。','The grocer reduced spoilage / by keeping dairy cold / and checking dates.','spoilage.s1 指食物变坏的过程，或因此造成的损失。','冷藏有助于减少食品腐败。'),M('The grocer reduced spoilage by leaving milk warm until it became unsafe to drink.','Cold storage and date checks helped prevent food from going bad.','让牛奶变质会增加而不是减少 spoilage。','meaning'),[q('What helped the grocer reduce spoilage?','keeping dairy cold and checking dates','leaving milk warm','selling food after it went bad','冷藏和查日期减少了变质损耗。',1,'context'),q('When did the grocer check product dates?','each morning','once every decade','only after customers complained','杂货商每天早上检查日期。',1,'context'),q('What does spoilage mean?','food going bad or the loss caused by it','a short formal talk','a sharp patch of color','spoilage 指食品变质或由此造成的损失。',1,'meaning'),q('Which store has less spoilage?','one that keeps milk cold and rotates stock','one that leaves dairy unrefrigerated','one that hides old dates','冷藏牛奶并轮换存货的商店 spoilage 更少。',1,'context')]);
P('spoken','Spoken is the past participle of speak; as an adjective it means expressed by voice rather than writing, or used to describe a person’s manner of talking.',[C('spoken.s1','口头的；口语的','The agreement was spoken, not written, so the partners later signed a document to record its terms.','这项协议是口头达成的，并非书面协议，因此合伙人后来签署文件记录条款。','The agreement was spoken / not written / so the partners recorded its terms.','spoken.s1 指通过声音表达，而不是写下来。','条款先口头约定，之后再书面记录。'),C('spoken.s2','（描述说话方式）…的','The softly spoken guide lowered her voice as the visitors entered the quiet archive.','参观者进入安静档案馆时，说话轻柔的讲解员压低了声音。','The softly spoken guide lowered her voice / as visitors entered / the archive.','spoken.s2 可放在副词或形容词后，描述一个人的说话方式。','softly spoken 描述讲解员的说话风格。')],M('The spoken agreement was recorded only in a signed document and never communicated aloud.','The partners first expressed the agreement verbally and wrote it down later.','从未口头表达的协议不能称作 spoken agreement。','meaning'),[q('How was the agreement first made?','by speaking rather than writing','through a signed document only','by a public concert','协议最初是口头达成的。',1,'context'),q('What did the partners do later?','signed a document recording the terms','forgot every term','moved the archive','合伙人后来签文件记录条款。',1,'context'),q('What does spoken mean in the agreement example?','expressed by voice rather than writing','written and printed in a book','quietly whispered by a guide only','这里 spoken 指口头表达的。',1,'meaning'),q('What does “softly spoken guide” describe?','the gentle way the guide talks','the guide’s written agreement','the archive’s lighting','softly spoken 描述讲解员轻声说话的方式。',2,'meaning')]);
P('spokesman','Spokesman combines spoke and man; it traditionally means a man who speaks officially for a group, or a representative voicing others’ views.',[C('spokesman.s1','（组织的）男发言人','The company spokesman answered reporters’ questions about the factory closure at a morning briefing.','公司的男发言人在上午简报会上回答了记者关于工厂关闭的问题。','The company spokesman answered reporters’ questions / about the factory closure / at a briefing.','spokesman.s1 按词形传统上指代表组织公开发言的男性。','他代表公司回应媒体。'),C('spokesman.s2','代言者；代表发声的人','As spokesman for the tenants, Daniel presented their shared concerns to the housing board.','丹尼尔作为租户代表，向住房委员会陈述了大家共同关心的问题。','Daniel served as spokesman for the tenants / presenting their shared concerns / to the board.','spokesman.s2 指替他人或群体表达观点的代表。','丹尼尔陈述租户共同意见。')],M('The company spokesman answered for the company while refusing to represent it or discuss its position.','The spokesman officially represented the company in answering reporters.','拒绝代表组织发言与 spokesman 的职责相反。','meaning'),[q('What issue did the company spokesman address?','the factory closure','the archive’s spoken agreement','the tenants’ garden','发言人回答了工厂关闭问题。',1,'context'),q('Whose concerns did Daniel present?','the tenants’ shared concerns','the company’s profits only','the reporters’ personal schedules','丹尼尔陈述了租户们共同关心的问题。',2,'context'),q('What does spokesman traditionally identify in the first example?','a man who speaks officially for an organization','a person who listens to a public speech','a written agreement','spokesman 传统上指组织的男性发言人。',1,'meaning'),q('What is Daniel’s role as spokesman?','representing the tenants’ views','closing the factory himself','editing an archive document','丹尼尔作为 spokesman 替租户群体表达意见。',2,'meaning')]);
P('spokesperson','Spokesperson combines spoke and person; it means someone chosen to make official statements or speak publicly for a group or cause.',[C('spokesperson.s1','（组织的）发言人','A government spokesperson confirmed the road closure and answered questions from local reporters.','政府发言人确认了道路封闭消息，并回答了当地记者的问题。','A government spokesperson confirmed the closure / and answered questions / from reporters.','spokesperson.s1 指受组织委托发布正式声明并回答问题的人。','发言人代表政府回应记者。'),C('spokesperson.s2','代言人；代表人物','The athlete became a spokesperson for safe cycling after recovering from a serious crash.','严重车祸康复后，这名运动员成为安全骑行的倡导代表。','The athlete became a spokesperson for safe cycling / after recovering / from a crash.','spokesperson.s2 指为某一群体、事业或理念公开发声的代表。','运动员公开倡导安全骑行。')],M('The government spokesperson denied being chosen to answer questions and refused to issue any statement.','The spokesperson represented the government and responded to reporters.','代表政府回答问题正是发言人的职责。','meaning'),[q('What did the government spokesperson confirm?','the road closure','the athlete’s race result','the factory’s profit','发言人确认了道路封闭消息。',1,'context'),q('What cause did the athlete support publicly?','safe cycling','factory closure','archive preservation only','运动员成为安全骑行的倡导代表。',2,'context'),q('What does spokesperson mean in the government example?','a person who makes official statements for an organization','a person who closes a road','a formal written contract','政府例句中的 spokesperson 指组织发言人。',1,'meaning'),q('What is the athlete’s spokesperson role?','publicly representing a cause','answering only for the government','writing a private agreement','运动员作为 spokesperson 公开代表安全骑行理念发声。',2,'meaning')]);
P('spokeswoman','Spokeswoman combines spoke and woman; it means a woman chosen to state a group’s position publicly.',C('spokeswoman.s1','女发言人','The union spokeswoman announced the new schedule and explained how members could submit questions.','工会女发言人公布了新日程，并说明会员如何提交问题。','The union spokeswoman announced the schedule / and explained how members / could submit questions.','spokeswoman.s1 指代表团体公开说明立场的女性。','她代表工会说明安排。'),M('The union spokeswoman represented no union and made no public statement on its behalf.','She announced the schedule and answered for the union.','不代表组织发言不符合 spokeswoman 的定义。','meaning'),[q('What did the union spokeswoman announce?','the new schedule','a canyon’s splendor','the company’s factory closure','工会女发言人公布了新日程。',1,'context'),q('How could members send questions?','by following the method she explained','by speaking only to the company spokesman','by mailing them to a museum','她说明了会员提交问题的方式。',1,'context'),q('What is a spokeswoman?','a woman chosen to state a group’s position publicly','a woman who watches an event','a person who writes a novel','spokeswoman 指代表团体公开发言的女性。',1,'meaning'),q('Which person is a spokeswoman?','a woman answering the press for a union','a spectator in the stadium','a silent attendee at a briefing','替工会回答媒体问题的女性是 spokeswoman。',1,'context')]);
P('spoliate','Spoliate comes from Latin spolia, “spoils”; it is a formal, uncommon verb meaning strip or plunder goods by force or illegal taking.',C('spoliate.s1','掠夺；强夺','The occupying troops tried to spoliate the village archive, taking records that belonged to its residents.','占领军试图掠夺村庄档案，带走属于居民的记录。','The troops tried to spoliate the archive / taking records / that belonged to residents.','spoliate.s1 指以武力或非法手段剥夺个人或地点的财物，属正式且少见用语。','档案中的记录被企图强行带走。'),M('The troops spoliated the archive by returning every record intact and taking nothing from the village.','They tried to plunder and remove the village’s records.','归还所有物品而未拿走任何东西不属于 spoliate。','meaning'),[q('What did the troops try to spoliate?','the village archive','the union schedule','the theater lighting','占领军试图掠夺村庄档案。',1,'context'),q('Whom did the records belong to?','the village residents','the occupying troops','the local reporters','这些记录属于村庄居民。',1,'context'),q('What does spoliate mean?','strip or plunder by force or illegal taking','repair an object carefully','officially answer a reporter','spoliate 指掠夺或强夺财物。',1,'meaning'),q('Which action is to spoliate an archive?','illegally removing its records','cataloguing its papers for residents','announcing its opening hours','非法带走档案记录属于 spoliate。',1,'context')]);
P('sponge','Sponge comes from Latin spongia; it can mean a porous sea animal/material, clean or absorb liquid with one, or get support without giving back.',[C('sponge.s1','海绵','The diver found a bright orange sponge attached to the shaded rock beneath the pier.','潜水员在码头下阴暗的岩石上发现了一块鲜橙色海绵。','The diver found an orange sponge / attached to shaded rock / beneath the pier.','sponge.s1 可指海生多孔动物，也可指用来清洗的柔软多孔材料。','海绵附着在水下岩石上。'),C('sponge.s2','用海绵擦；吸掉','Please sponge the spilled juice from the counter before it reaches the electrical outlet.','请用海绵把柜台上洒出的果汁擦掉，别让它流到电源插座旁。','Please sponge the juice from the counter / before it reaches / the outlet.','sponge.s2 作动词，指用海绵清洁或吸走液体。','用海绵吸掉果汁。'),C('sponge.s3','揩油；依赖他人生活','He continued to sponge off his cousin for meals and rent instead of looking for work.','他不找工作，继续靠表亲供饭和付房租。','He continued to sponge off his cousin / for meals and rent / instead of finding work.','sponge.s3 指不回报地向他人索取钱财或食物。','他靠表亲提供生活费用。')],M('He sponged off his cousin by paying rent and buying every meal for both of them.','He relied on his cousin for food and rent without giving anything in return.','承担房租和饭钱不是依赖他人白拿。','meaning'),[q('Where was the orange sponge found?','on shaded rock beneath the pier','on the counter beside the outlet','inside the union office','潜水员在码头下的岩石上发现橙色海绵。',1,'context'),q('What should be sponged from the counter?','the spilled juice','the electrical outlet','the pier’s shadow','应把柜台上的果汁擦掉。',1,'context'),q('What did the man sponge off his cousin?','meals and rent','a porous sea animal','a union schedule','他靠表亲提供饭食和房租。',3,'context'),q('What does sponge off someone mean?','get food or money from them without giving back','clean their counter with a sponge','lend them rent money','sponge off someone 指不回报地依赖对方供给。',3,'meaning')]);
P('sponger','Sponger is formed from sponge and -er; it means a person who persistently gets money, food, or favors without paying back.',C('sponger.s1','白吃白喝的人；揩油者','The sponger arrived at every family meal but never brought food or offered to help with the dishes.','这个白吃白喝的人每次家庭聚餐都来，却从不带食物，也不帮忙洗碗。','The sponger arrived at every meal / but never brought food / or helped clean.','sponger.s1 指总想从别人那里白拿钱、食物或款待的人。','他只接受款待，从不回报。'),M('The sponger paid for every family meal and cooked for the whole household each night.','He repeatedly accepted meals without contributing food or help.','付钱并做饭是贡献，不是白吃白喝。','meaning'),[q('What did the sponger never bring?','food','a union statement','a porous sea animal','他从不带食物来聚餐。',1,'context'),q('What chore did he avoid helping with?','washing the dishes','repairing the pier','writing the schedule','他不帮忙洗碗。',1,'context'),q('What is a sponger?','a person who takes food or favors without returning anything','a person who pays for every meal','a person who cleans with a sponge','sponger 指白拿他人钱财或款待的人。',1,'meaning'),q('Which guest is a sponger?','someone who accepts dinner repeatedly but never contributes','someone who brings food and washes dishes','someone who sponsors the meal','总来吃饭却从不出力的人是 sponger。',1,'context')]);
P('sponsor','Sponsor is from Latin sponsor, “surety”; it can mean a person/company funding an event, a proposer or official supporter, or pay for/support something.',[C('sponsor.s1','赞助者；赞助商','A local bank became the main sponsor of the youth orchestra and paid for its instruments.','当地一家银行成为青年管弦乐团的主要赞助商，并为乐器付款。','The bank became the orchestra’s sponsor / and paid / for its instruments.','sponsor.s1 指为活动、项目或个人支付费用的人或公司。','银行资助乐团购买乐器。'),C('sponsor.s2','发起人；保证人','Senator Lee sponsored the clean-water bill and argued for it during the committee hearing.','李参议员发起了清洁饮水法案，并在委员会听证会上为法案辩护。','Senator Lee sponsored the bill / and argued for it / at the hearing.','sponsor.s2 指提出计划或正式支持某人的发起者、保证人。','参议员提出并支持法案。'),C('sponsor.s3','赞助；发起；资助','The company agreed to sponsor a free coding workshop for students in the rural district.','公司同意资助农村地区学生参加免费的编程工作坊。','The company agreed to sponsor the workshop / for rural students / at no cost.','sponsor.s3 作动词可指出资支持活动，也可指发起提案。','公司支付工作坊费用。')],M('The bank sponsored the orchestra by refusing all payment for instruments and withdrawing its support.','The bank provided financial support for the orchestra’s instruments.','拒绝资助并撤回支持与 sponsor 相反。','meaning'),[q('What did the bank pay for?','the orchestra’s instruments','the clean-water committee','the students’ meals','银行为乐团的乐器付款。',1,'context'),q('What did Senator Lee sponsor?','the clean-water bill','the youth orchestra’s violin','the archive tour','李参议员发起并支持清洁饮水法案。',2,'context'),q('What did the company agree to sponsor?','a free coding workshop','a medical scan','a family dinner','公司同意资助免费的编程工作坊。',3,'context'),q('What does sponsor mean as a verb in the orchestra sentence?','pay for or support an activity','watch it without joining','divide its instruments into parts','公司资助活动时，sponsor 指出资支持。',1,'meaning')]);
P('sponsorship','Sponsorship is formed from sponsor and -ship; it means financial backing or other support for an event, team, or student.',C('sponsorship.s1','赞助；资助','The student received a two-year sponsorship that covered tuition and laboratory fees.','这名学生获得为期两年的资助，用于支付学费和实验室费用。','The student received sponsorship / covering tuition / and laboratory fees.','sponsorship.s1 指个人或公司为活动、团队或学生提供的资金或支持。','资助支付学生教育费用。'),M('The student’s sponsorship required her to pay every fee herself and gave her no financial or other support.','The sponsorship provided money to cover tuition and lab costs.','不给予任何支持就不是 sponsorship。','meaning'),[q('How long did the student’s sponsorship last?','two years','two days','one semester only','学生获得为期两年的资助。',1,'context'),q('Which costs did it cover?','tuition and laboratory fees','a theater’s lighting repair','the family meal dishes','资助支付学费和实验室费用。',1,'context'),q('What is sponsorship?','financial backing or support for a person or event','a person who watches a match','a message sent by phone','sponsorship 指提供资金或其他支持。',1,'meaning'),q('Which arrangement is sponsorship?','a company funds a student’s education costs','a student pays all fees with no assistance','a reporter writes a public statement','公司资助学生教育费用属于 sponsorship。',1,'context')]);
})();
